\\\/cdn.shopify.com\\\\/s\\\\/files\\\\/1\\\\/0566\\\\/1209\\\\/4037\\\\/files\\\\/Mini_red.webp?v=1716782465\\\",\\n        \\\"thumb_6_url\\\": \\\"https:\\\\/\\\\/cdn.shopify.com\\\\/s\\\\/files\\\\/1\\\\/0566\\\\/1209\\\\/4037\\\\/files\\\\/Mini_Sandstone.webp?v=1716782465\\\"\\n      }\\n    },\\n    \\\"banner\\\": {\\n      \\\"type\\\": \\\"zhp-pdp-banner\\\",\\n      \\\"settings\\\": {\\n        \\\"banner_image_url\\\": \\\"https:\\\\/\\\\/cdn.shopify.com\\\\/s\\\\/files\\\\/1\\\\/0566\\\\/1209\\\\/4037\\\\/products\\\\/8-tone_6-inch_steel_tongue_panda_drum_help_by_a_little_girl.jpg?v=1716782465\\\",\\n        \\\"heading\\\": \\\"Tuned to 432 Hz: The Frequency of Natural Healing\\\"\\n      }\\n    },\\n    \\\"experience\\\": {\\n      \\\"type\\\": \\\"zhp-pdp-experience\\\",\\n      \\\"settings\\\": {\\n        \\\"feature_image_url\\\": \\\"https:\\\\/\\\\/cdn.shopify.com\\\\/s\\\\/files\\\\/1\\\\/0566\\\\/1209\\\\/4037\\\\/products\\\\/panda-drum-6-inch-steel-tongue-drum.jpg?v=1716782465\\\",\\n        \\\"title\\\": \\\"Zero Musical Training Required\\\"\\n      }\\n    },\\n    \\\"included\\\": {\\n      \\\"type\\\": \\\"zhp-pdp-included\\\",\\n      \\\"settings\\\": {\\n        \\\"included_image_url\\\": \\\"https:\\\\/\\\\/cdn.shopify.com\\\\/s\\\\/files\\\\/1\\\\/0566\\\\/1209\\\\/4037\\\\/products\\\\/1Box_Drum_8_new.jpg?v=1716782465\\\",\\n        \\\"title\\\": \\\"Everything You Need to Begin Immediately\\\"\\n      }\\n    },\\n    \\\"specs\\\": {\\n      \\\"type\\\": \\\"zhp-pdp-specs\\\",\\n      \\\"settings\\\": {\\n        \\\"title\\\": \\\"Technical Specifications\\\",\\n        \\\"spec_diameter\\\": \\\"6 Inches (15.2 cm) Pocket Mini\\\",\\n        \\\"spec_material\\\": \\\"Tempered Carbon-Titanium Surgical Alloy Steel\\\",\\n        \\\"spec_tuning\\\": \\\"Pentatonic C-Major Scale (8 Notes)\\\",\\n        \\\"spec_frequency\\\": \\\"432 Hz Natural Biological Resonance\\\",\\n        \\\"spec_tones\\\": \\\"8 Acoustic Tongues\\\",\\n        \\\"spec_weight\\\": \\\"1.3 lbs (0.6 kg) Ultra Portable\\\",\\n        \\\"spec_finish\\\": \\\"Baked Electrostatic Pearlescent Protective Coating\\\"\\n      }\\n    },\\n    \\\"shipping\\\": {\\n      \\\"type\\\": \\\"zhp-pdp-shipping\\\",\\n      \\\"settings\\\": {}\\n    },\\n    \\\"reviews\\\": {\\n      \\\"type\\\": \\\"zhp-pdp-reviews\\\",\\n      \\\"blocks\\\": {\\n        \\\"rev_1\\\": {\\n          \\\"type\\\": \\\"review\\\",\\n          \\\"settings\\\": {\\n            \\\"author\\\": \\\"Kimberly Green\\\",\\n            \\\"title\\\": \\\"My 3-year-old son loves this so much\\\",\\n            \\\"text\\\": \\\"He used to throw tantrums before naptime. Now he sits with his mini drum and taps softly until he is calm. It is indestructible and sounds so peaceful.\\\",\\n            \\\"meta\\\": \\\"Zavelyn Drum™ Mini (Blue) • Atlanta, GA\\\"\\n          }\\n        },\\n        \\\"rev_2\\\": {\\n          \\\"type\\\": \\\"review\\\",\\n          \\\"settings\\\": {\\n            \\\"author\\\": \\\"Daniel Howard\\\",\\n            \\\"title\\\": \\\"Pocket sound bowl for hiking and backpacking\\\",\\n            \\\"text\\\": \\\"Weighs barely a pound. Fits in my daypack side pocket. Sitting at mountain summits playing acoustic notes into the valley is pure magic.\\\",\\n            \\\"meta\\\": \\\"Zavelyn Drum™ Mini (Black) • Salt Lake City, UT\\\"\\n          }\\n        },\\n        \\\"rev_3\\\": {\\n          \\\"type\\\": \\\"review\\\",\\n          \\\"settings\\\": {\\n            \\\"author\\\": \\\"Stephanie Lopez\\\",\\n            \\\"title\\\": \\\"Impossible to play a bad note\\\",\\n            \\\"text\\\": \\\"The pentatonic tuning means every note blends harmoniously. You cannot make a mistake. It is genuinely fun and soothing for anyone.\\\",\\n            \\\"meta\\\": \\\"Zavelyn Drum™ Mini (Pink) • Tampa, FL\\\"\\n          }\\n        },\\n        \\\"rev_4\\\": {\\n          \\\"type\\\": \\\"review\\\",\\n          \\\"settings\\\": {\\n            \\\"author\\\": \\\"Jonathan Wood\\\",\\n            \\\"title\\\": \\\"Surprising volume and resonance for 6 inches\\\",\\n            \\\"text\\\": \\\"Expected it to sound like a toy, but it rings with genuine bell clarity and sustain. The mini rubber mallets work wonders.\\\",\\n            \\\"meta\\\": \\\"Zavelyn Drum™ Mini (White) • Nashville, TN\\\"\\n          }\\n        },\\n        \\\"rev_5\\\": {\\n          \\\"type\\\": \\\"review\\\",\\n          \\\"settings\\\": {\\n            \\\"author\\\": \\\"Rachel Morris\\\",\\n            \\\"title\\\": \\\"Great screen-free gift for grandchildren\\\",\\n            \\\"text\\\": \\\"Gave one to each of my granddaughters. They spent hours playing songs together instead of staring at iPads. A grandparent win!\\\",\\n            \\\"meta\\\": \\\"2x Zavelyn Drum™ Mini Explorer Pack • Chicago, IL\\\"\\n          }\\n        },\\n        \\\"rev_6\\\": {\\n          \\\"type\\\": \\\"review\\\",\\n          \\\"settings\\\": {\\n            \\\"author\\\": \\\"Ethan Turner\\\",\\n            \\\"title\\\": \\\"Lovely desk accessory for stress relief\\\",\\n            \\\"text\\\": \\\"I keep it right under my computer monitor. During long Zoom calls or stressful emails, a soft tap restores immediate tranquility.\\\",\\n            \\\"meta\\\": \\\"Zavelyn Drum™ Mini (Sandstone) • Austin, TX\\\"\\n          }\\n        },\\n        \\\"rev_7\\\": {\\n          \\\"type\\\": \\\"review\\\",\\n          \\\"settings\\\": {\\n            \\\"author\\\": \\\"Megan Brooks\\\",\\n            \\\"title\\\": \\\"Cute, durable and beautifully tuned\\\",\\n            \\\"text\\\": \\\"The red paint is thick and flawless. Has survived multiple drops onto carpet without a scratch or going out of tune.\\\",\\n            \\\"meta\\\": \\\"Zavelyn Drum™ Mini (Red) • Denver, CO\\\"\\n          }\\n        },\\n        \\\"rev_8\\\": {\\n          \\\"type\\\": \\\"review\\\",\\n          \\\"settings\\\": {\\n            \\\"author\\\": \\\"Anthony Lee\\\",\\n            \\\"title\\\": \\\"Perfect introductory instrument\\\",\\n            \\\"text\\\": \\\"Builds hand-eye coordination and auditory sensitivity in young kids. Numbered booklet is very well laid out.\\\",\\n            \\\"meta\\\": \\\"Zavelyn Drum™ Mini (White) • Seattle, WA\\\"\\n          }\\n        },\\n        \\\"rev_9\\\": {\\n          \\\"type\\\": \\\"review\\\",\\n          \\\"settings\\\": {\\n            \\\"author\\\": \\\"Heather Cox\\\",\\n            \\\"title\\\": \\\"Sweet and gentle lullabies\\\",\\n            \\\"text\\\": \\\"I play Twinkle Twinkle Little Star on this every evening in our baby nursery. Instantly settles our newborn.\\\",\\n            \\\"meta\\\": \\\"Zavelyn Drum™ Mini (Pink Tan) • Charlotte, NC\\\"\\n          }\\n        },\\n        \\\"rev_10\\\": {\\n          \\\"type\\\": \\\"review\\\",\\n          \\\"settings\\\": {\\n            \\\"author\\\": \\\"William Bailey\\\",\\n            \\\"title\\\": \\\"Exceeded all expectations\\\",\\n            \\\"text\\\": \\\"Compact, affordable, beautifully packaged, and sounds genuinely healing. Couldn’t be happier with this purchase.\\\",\\n            \\\"meta\\\": \\\"Zavelyn Drum™ Mini (Blue) • Portland, OR\\\"\\n          }\\n        }\\n      },\\n      \\\"block_order\\\": [\\n        \\\"rev_1\\\",\\n        \\\"rev_2\\\",\\n        \\\"rev_3\\\",\\n        \\\"rev_4\\\",\\n        \\\"rev_5\\\",\\n        \\\"rev_6\\\",\\n        \\\"rev_7\\\",\\n        \\\"rev_8\\\",\\n        \\\"rev_9\\\",\\n        \\\"rev_10\\\"\\n      ],\\n      \\\"settings\\\": {\\n        \\\"title\\\": \\\"Loved By Thousands of Sound Seekers\\\",\\n        \\\"rating_summary\\\": \\\"950+ Verified Practitioner Reviews\\\"\\n      }\\n    },\\n    \\\"faq\\\": {\\n      \\\"type\\\": \\\"zhp-pdp-faq\\\",\\n      \\\"blocks\\\": {\\n        \\\"faq_1\\\": {\\n          \\\"type\\\": \\\"faq\\\",\\n          \\\"settings\\\": {\\n            \\\"question\\\": \\\"Do I need any prior musical experience to play?\\\",\\n            \\\"answer\\\": \\\"None whatsoever! Zavelyn Drums are designed to be completely intuitive. Because every note is tuned to natural harmonic scales, there are zero discordant or 'bad' notes. You can play purely by intuition, or follow the numbered songbook.\\\"\\n          }\\n        },\\n        \\\"faq_2\\\": {\\n          \\\"type\\\": \\\"faq\\\",\\n          \\\"settings\\\": {\\n            \\\"question\\\": \\\"What does 432 Hz tuning mean?\\\",\\n            \\\"answer\\\": \\\"Standard modern music is tuned to 440 Hz, which can sound tense. 432 Hz is the natural harmonic frequency historically used by classical masters. Scientific studies indicate 432 Hz produces calmer emotional responses, lower heart rates, and enhanced meditation states.\\\"\\n          }\\n        },\\n        \\\"faq_3\\\": {\\n          \\\"type\\\": \\\"faq\\\",\\n          \\\"settings\\\": {\\n            \\\"question\\\": \\\"Should I play with the mallets or my hands?\\\",\\n            \\\"answer\\\": \\\"Both! The included weighted bamboo mallets produce a bright, loud, crystal-clear bell resonance with minimum effort. Playing with your hands or the silicone finger picks creates a softer, warmer, and more intimate tone ideal for quiet meditation.\\\"\\n          }\\n        },\\n        \\\"faq_4\\\": {\\n          \\\"type\\\": \\\"faq\\\",\\n          \\\"settings\\\": {\\n            \\\"question\\\": \\\"Will the drum ever go out of tune?\\\",\\n            \\\"answer\\\": \\\"No. The acoustic tongues are laser-cut from high-grade tempered alloy steel and heat-treated. Unless subjected to severe physical deformation, the instrument will maintain its pitch calibration for decades.\\\"\\n          }\\n        },\\n        \\\"faq_5\\\": {\\n          \\\"type\\\": \\\"faq\\\",\\n          \\\"settings\\\": {\\n            \\\"question\\\": \\\"What is your return policy?\\\",\\n            \\\"answer\\\": \\\"We offer a 90-Day Risk-Free Trial. If you don't feel a noticeable sense of relaxation, joy, and peace when playing your Zavelyn Drum™, return it for a 100% full refund with no questions asked.\\\"\\n          }\\n        }\\n      },\\n      \\\"block_order\\\": [\\n        \\\"faq_1\\\",\\n        \\\"faq_2\\\",\\n        \\\"faq_3\\\",\\n        \\\"faq_4\\\",\\n        \\\"faq_5\\\"\\n      ],\\n      \\\"settings\\\": {}\\n    },\\n    \\\"sticky_bar\\\": {\\n      \\\"type\\\": \\\"zhp-pdp-sticky-bar\\\",\\n      \\\"settings\\\": {\\n        \\\"sticky_image\\\": \\\"shopify:\\\\/\\\\/shop_images\\\\/tr-ng-v-ng-n-n-trong-su-t.png\\\",\\n        \\\"sticky_image_url\\\": \\\"https:\\\\/\\\\/cdn.shopify.com\\\\/s\\\\/files\\\\/1\\\\/0566\\\\/1209\\\\/4037\\\\/files\\\\/Mini_white.webp?v=1716782465\\\",\\n        \\\"title\\\": \\\"Zavelyn Drum™ Mini\\\",\\n        \\\"price\\\": \\\"109.95\\\",\\n        \\\"compare_at\\\": \\\"179.95\\\"\\n      }\\n    }\\n  },\\n  \\\"order\\\": [\\n    \\\"hero\\\",\\n    \\\"banner\\\",\\n    \\\"experience\\\",\\n    \\\"included\\\",\\n    \\\"specs\\\",\\n    \\\"shipping\\\",\\n    \\\"reviews\\\",\\n    \\\"faq\\\",\\n    \\\"sticky_bar\\\"\\n  ]\\n}\\n\","}
