  padding-top: 18px;
  box-sizing: border-box;
}

.wf-faq-answer p {
  margin: 0;
  color: #333333;
  line-height: 1.7;
}

.wf-faq-item.active .wf-faq-answer {
  display: block;
  animation: wfFaqFade 0.25s ease-out;
}

@keyframes wfFaqFade {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 767px) {
  .wf-faq-section {
    padding: 56px 0;
