    font-size: 14.5px;
  }
  .wf-faq-question {
    padding: 18px 18px;
    font-size: 15.5px;
  }
  .wf-faq-answer {
    padding: 0 18px 18px;
    font-size: 14.5px;
    padding-top: 14px;
  }
  .wf-faq-arrow {
    width: 24px;
    height: 24px;
    font-size: 18px;
  }
}
</style>

<script>
(function() {
  function toggleWfFaq(btn) {
    if (!btn) return;
    var item = btn.closest('.wf-faq-item');
    if (!item) return;
    var accordion = item.closest('.wf-faq-accordion');
    var isCurrentlyActive = item.classList.contains('active');

    if (accordion) {
      var allItems = accordion.querySelectorAll('.wf-faq-item');
      for (var i = 0; i < allItems.length; i++) {
        allItems[i].classList.remove('active');
        var questionBtn = allItems[i].querySelector('.wf-faq-question');
        if (questionBtn) questionBtn.setAttribute('aria-expanded', 'false');
      }
    }

    if (!isCurrentlyActive) {
      item.classList.add('active');
      btn.setAttribute('aria-expanded', 'true');
    }
  }

  // Expose globally so onclick="toggleWfFaq(this)" works seamlessly
  window.toggleWfFaq = toggleWfFaq;

  // Also bind event listeners once DOM is ready as progressive enhancement
  function initFaqListeners() {
    var buttons = document.querySelectorAll('.wf-faq-question');
    for (var i = 0; i < buttons.length; i++) {
      if (!buttons[i].dataset.faqBound) {
        buttons[i].dataset.faqBound = 'true';
        buttons[i].addEventListener('click', function(e) {
          toggleWfFaq(this);
        });
      }
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initFaqListeners);
  } else {
    initFaqListeners();
  }
})();
</script>

