  'Change Reason',
  'Redirect Required',
  'Ads Traffic Risk',
  'SEO Risk',
  'Content Verification',
  'Classification',
  'Approval Status'
];

function escapeCsv(val) {
  if (val === null || val === undefined) return '';
  const s = String(val).replace(/"/g, '""');
  return `"${s}"`;
}

const csvRows = [headers.join(',')];
plan.forEach(r => {
  csvRows.push([
    escapeCsv(r.productId),
