    escapeCsv(r.classification),
    escapeCsv(r.approvalStatus)
  ].join(','));
});

fs.writeFileSync('scripts/ZAVELYN_SEO_CATALOG_MIGRATION_PLAN.csv', csvRows.join('\n'));

