const handles = plan.map(p => p.proposedUrlHandle);
const seoTitles = plan.map(p => p.proposedSeoPageTitle);
const uniqueTitles = new Set(titles).size;
const uniqueHandles = new Set(handles).size;
const uniqueSeo = new Set(seoTitles).size;

console.log(JSON.stringify({
  total: plan.length,
  uniqueTitles,
  uniqueHandles,
  uniqueSeo
}, null, 2));
"

