import fs from 'fs';

const CLIENT_ID = '172e9e29abd0fe12f671d8441479c7c2';
const CLIENT_SECRET = process.env.SHOPIFY_API_SECRET || 'shpss_REDACTED_SECRET';
const SHOP = 'dsdujr-vn.myshopify.com';

async function getAccessToken() {
  const tRes = await fetch('https://' + SHOP + '/admin/oauth/access_token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ client_id: CLIENT_ID, client_secret: CLIENT_SECRET, grant_type: 'client_credentials' })
  });
  const data = await tRes.json();
  return data.access_token;
}

async function run() {
  const token = await getAccessToken();
  console.log('Got access token');

  // List assets from draft and live
  const themes = [
    { id: '187597717689', name: 'Draft Theme' },
    { id: '186607567033', name: 'Live Theme' }
  ];

  const keywords = [/60[\s-]?day/i, /90[\s-]?day/i, /30[\s-]?day/i, /money[\s-]?back/i, /risk[\s-]?free/i, /guarantee/i, /trial/i];
  const findings = [];

  for (const t of themes) {
    console.log('Scanning theme:', t.name, t.id);
    const res = await fetch('https://' + SHOP + '/admin/api/2024-10/themes/' + t.id + '/assets.json', {
      headers: { 'X-Shopify-Access-Token': token }
    });
    const { assets } = await res.json();
    console.log('Total assets in', t.name, assets.length);

    // Filter liquid, json
    const textAssets = assets.filter(a => a.key.endsWith('.liquid') || a.key.endsWith('.json'));
    console.log('Text assets to inspect:', textAssets.length);

    for (const a of textAssets) {
      // fetch asset content
      try {
        const aRes = await fetch('https://' + SHOP + '/admin/api/2024-10/themes/' + t.id + '/assets.json?asset[key]=' + encodeURIComponent(a.key), {
          headers: { 'X-Shopify-Access-Token': token }
        });
        const aJson = await aRes.json();
        const content = aJson.asset?.value || '';
        if (!content) continue;

        for (const kw of keywords) {
          if (kw.test(content)) {
            // Find specific matching lines
            const lines = content.split('\n');
            lines.forEach((line, idx) => {
              if (kw.test(line)) {
                findings.push({
                  theme: t.name,
                  themeId: t.id,
                  file: a.key,
                  line: idx + 1,
                  snippet: line.trim().slice(0, 200),
                  match: kw.toString()
                });
              }
            });
          }
        }
      } catch (err) {
        console.error('Error fetching', a.key, err.message);
      }
    }
  }

  fs.writeFileSync('scripts/theme_guarantee_matches.json', JSON.stringify(findings, null, 2));
  console.log('Total matches found:', findings.length);
}

run().catch(console.error);
"

