import fs from 'fs';
import path from 'path';

const keywords = [/60[\s-]?day/i, /90[\s-]?day/i, /30[\s-]?day/i, /money[\s-]?back/i, /risk[\s-]?free/i, /guarantee/i, /trial/i];

function walk(dir, fileList = []) {
  const files = fs.readdirSync(dir);
  for (const f of files) {
    if (f === 'node_modules' || f === '.git' || f === '.gemini' || f === 'theme_audit') continue;
    const p = path.join(dir, f);
    try {
      const stat = fs.statSync(p);
      if (stat.isDirectory()) {
        if (!p.includes('node_modules') && !p.includes('.git')) {
          walk(p, fileList);
        }
      } else if (f.endsWith('.liquid') || f.endsWith('.json') || f.endsWith('.html')) {
        fileList.push(p);
      }
    } catch (e) {}
  }
  return fileList;
}

const allFiles = walk('sections').concat(walk('templates')).concat(walk('assets'));
