    await new Promise(r => setTimeout(r, 4000));
    const snapDesk = await send('Page.captureScreenshot', { format: 'png' });
    const deskPath = path.join(ARTIFACTS_DIR, 'qa_batch1_zavelyn-sensory-floor-mats_desktop_1440.png');
