import fs from 'fs';
import { getAccessToken, SHOP, API_VERSION } from './batch1_config.mjs';

async function testCompare() {
  const token = await getAccessToken();
  const raw = JSON.parse(fs.readFileSync('scripts/raw_catalog_products.json', 'utf8'));
  const rawMap = new Map(raw.map(p => [p.id, p]));

  const q = `
    query testCompare {
      products(first: 10, query: "status:ACTIVE") {
        nodes {
          id
          vendor
          productType
          description
          totalVariants
        }
      }
    }
  `;

  const res = await fetch(`https://${SHOP}/admin/api/${API_VERSION}/graphql.json`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'X-Shopify-Access-Token': token },
    body: JSON.stringify({ query: q })
  });
  const data = await res.json();
  const live = data.data?.products?.nodes || [];

  for (const lp of live) {
    const rp = rawMap.get(lp.id);
    console.log('Product:', lp.id);
    console.log(' - Vendor matches:', rp.vendor === lp.vendor, `("${rp.vendor}" vs "${lp.vendor}")`);
    console.log(' - Type matches:', rp.productType === lp.productType, `("${rp.productType}" vs "${lp.productType}")`);
    console.log(' - Desc matches:', rp.description === lp.description);
  }
}

testCompare().catch(console.error);

