_stars\\\": 5,\\n            \\\"item_12_name\\\": \\\"Sarah J.\\\",\\n            \\\"item_12_date\\\": \\\"\\\",\\n            \\\"item_12_text\\\": \\\"This brace has honestly changed my daily walks. I used to catch my toe on the sidewalk cracks constantly, but now I feel so much safer.\\\",\\n            \\\"item_12_fallback\\\": \\\"cdf-loox-12.jpg\\\",\\n            \\\"item_12_verified\\\": true,\\n            \\\"item_12_stars\\\": 5\\n          }\\n        },\\n        \\\"sec_trust\\\": {\\n          \\\"type\\\": \\\"sec_trust\\\",\\n          \\\"settings\\\": {\\n            \\\"icon_1_glyph\\\": \\\"🚚\\\",\\n            \\\"icon_1_title\\\": \\\"Free Ship on Buy 2\\\",\\n            \\\"icon_1_text\\\": \\\"$4.95 shipping on Buy 1\\\",\\n            \\\"icon_2_glyph\\\": \\\"↺\\\",\\n            \\\"icon_2_title\\\": \\\"30 Days Guarantee\\\",\\n            \\\"icon_2_text\\\": \\\"Didn't like it? return it\\\",\\n            \\\"icon_3_glyph\\\": \\\"🔒\\\",\\n            \\\"icon_3_title\\\": \\\"Secure Payment\\\",\\n            \\\"icon_3_text\\\": \\\"Secure and trusted credit card provider\\\",\\n            \\\"icon_4_glyph\\\": \\\"♥\\\",\\n            \\\"icon_4_title\\\": \\\"Happy Customers\\\",\\n            \\\"icon_4_text\\\": \\\"Thousands of happy customers worldwide\\\"\\n          }\\n        },\\n        \\\"sec_footer\\\": {\\n          \\\"type\\\": \\\"sec_footer\\\",\\n          \\\"settings\\\": {\\n            \\\"rights\\\": \\\"All Rights Reserved.\\\",\\n            \\\"privacy_label\\\": \\\"Privacy Policy\\\",\\n            \\\"terms_label\\\": \\\"Terms of Service\\\",\\n            \\\"email\\\": \\\"support@zavelyn.com\\\",\\n            \\\"sticky_copy\\\": \\\"Zavelyn Foot Drop AFO Brace — 50% OFF\\\",\\n            \\\"sticky_cta\\\": \\\"Add to cart\\\"\\n          }\\n        }\\n      },\\n      \\\"block_order\\\": [\\n        \\\"sec_gallery\\\",\\n        \\\"sec_hero\\\",\\n        \\\"sec_intro\\\",\\n        