import fs from 'fs';
import path from 'path';
import { getAccessToken, SHOP, API_VERSION } from './batch1_config.mjs';

const DRAFT_THEME_ID = '187597717689';

async function fixHomepageSections() {
  const token = await getAccessToken();
  const headers = { 'X-Shopify-Access-Token': token, 'Content-Type': 'application/json' };

  const targets = [
    {
      key: 'sections/zavelyn-pain-solution.liquid',
      replacements: [
        {
          from: 'Put us to the test completely risk-free. Try any Zavelyn product on your homestead, jobsite, or home for a full 60 days.',
          to: 'Put us to the test with our 30-day money-back guarantee. Try any Zavelyn product on your homestead, jobsite, or home.'
        },
        {
          from: 'Put us to the test completely risk-free.',
          to: 'Put us to the test with complete peace of mind.'
        },
        {
          from: 'for a full 60 days.',
          to: 'with our 30-day satisfaction guarantee.'
        }
      ]
    },
    {
      key: 'sections/zavelyn-comparison.liquid',
      replacements: [
        {
          from: '<td><strong>Risk-Free Guarantee</strong></td>',
          to: '<td><strong>Satisfaction Guarantee</strong></td>'
        },
        {
          from: '60-Day 100% Money-Back Trial',
          to: '30-Day Money-Back Guarantee'
        }
      ]
    }
  ];

  for (const item of targets) {
    console.log(`Checking ${item.key}...`);
    const getUrl = `https://${SHOP}/admin/api/${API_VERSION}/themes/${DRAFT_THEME_ID}/assets.json?asset[key]=${encodeURIComponent(item.key)}`;
    const res = await fetch(getUrl, { headers });
    const data = await res.json();
    let val = data.asset?.value;
    if (!val) {
      console.log(`Asset ${item.key} not found or empty.`);
      continue;
    }

    let modified = val;
    for (const r of item.replacements) {
      if (modified.includes(r.from)) {
        modified = modified.replaceAll(r.from, r.to);
        console.log(`Replaced "${r.from}" in ${item.key}`);
      }
    }

    if (modified !== val) {
      const putUrl = `https://${SHOP}/admin/api/${API_VERSION}/themes/${DRAFT_THEME_ID}/assets.json`;
      const putRes = await fetch(putUrl, {
        method: 'PUT',
        headers,
        body: JSON.stringify({ asset: { key: item.key, value: modified } })
      });
      const putData = await putRes.json();
      if (putData.asset) {
        console.log(`[SUCCESS] Updated ${item.key}`);
      } else {
        console.error(`[ERROR] Failed to update ${item.key}:`, putData.errors);
      }
    } else {
      console.log(`No changes needed for ${item.key}`);
    }
  }
}

fixHomepageSections();

import { getAccessToken, SHOP, API_VERSION } from './batch1_config.mjs';

async function listComparisonSections() {
  const token = await getAccessToken();
  const res = await fetch(`https://${SHOP}/admin/api/${API_VERSION}/themes/187597717689/assets.json`, {
    headers: { 'X-Shopify-Access-Token': token }
  });
  const data = await res.json();
  const comparisonAssets = (data.assets || []).filter(a => a.key.includes('comp') || a.key.includes('table'));
  console.log('Matching assets:', comparisonAssets.map(a => a.key));
}
listComparisonSections();

import { getAccessToken, SHOP, API_VERSION } from './batch1_config.mjs';

const DRAFT_THEME_ID = '187597717689';

async function updateComparisonElixir() {
  const token = await getAccessToken();
  const headers = { 'X-Shopify-Access-Token': token, 'Content-Type': 'application/json' };

  const key = 'sections/zavelyn-comparison-elixir.liquid';
  const getUrl = `https://${SHOP}/admin/api/${API_VERSION}/themes/${DRAFT_THEME_ID}/assets.json?asset[key]=${encodeURIComponent(key)}`;
  const res = await fetch(getUrl, { headers });
  const data = await res.json();
  let val = data.asset?.value || '';

  console.log('Matches in', key, ':', val.match(/risk[- ]free|60[- ]day|90[- ]day/gi));

  let modified = val
    .replaceAll('<td><strong>Risk-Free Guarantee</strong></td>', '<td><strong>Satisfaction Guarantee</strong></td>')
    .replaceAll('60-Day 100% Money-Back Trial', '30-Day Money-Back Guarantee')
    .replaceAll('60-Day Risk-Free Guarantee', '30-Day Money-Back Guarantee')
    .replaceAll('Risk-Free Guarantee', 'Satisfaction Guarantee');

  if (modified !== val) {
    const putUrl = `https://${SHOP}/admin/api/${API_VERSION}/themes/${DRAFT_THEME_ID}/assets.json`;
    const putRes = await fetch(putUrl, {
      method: 'PUT',
      headers,
      body: JSON.stringify({ asset: { key, value: modified } })
    });
    const putData = await putRes.json();
    if (putData.asset) {
      console.log(`[SUCCESS] Updated ${key}`);
    } else {
      console.error(`[ERROR] Failed to update ${key}:`, putData.errors);
    }
  } else {
    console.log(`No changes needed for ${key}`);
  }
}

updateComparisonElixir();

import fs from 'fs';
import { getAccessToken, SHOP, API_VERSION } from './batch1_config.mjs';

const TARGET_THEME_ID = '187597717689';
const PREVIOUS_LIVE_ID = '186607567033';

async function publishTheme() {
  console.log('========================================================================');
  console.log('ZAVELYN 2.0 — LIVE PUBLISH EXECUTION');
  console.log(`Publishing Theme ID: ${TARGET_THEME_ID} to role: "main"`);
  console.log(`Preserving Old Live Theme ID: ${PREVIOUS_LIVE_ID} as backup`);
  console.log('========================================================================\n');

  const token = await getAccessToken();
  const headers = {
    'X-Shopify-Access-Token': token,
    'Content-Type': 'application/json'
  };

  // Step 1: Check current themes state
  console.log('Step 1: Checking pre-publish themes status...');
  const preRes = await fetch(`https://${SHOP}/admin/api/${API_VERSION}/themes.json`, { headers });
  const preData = await preRes.json();
  const currentMain = preData.themes.find(t => t.role === 'main');
  console.log(`Current Main Theme: "${currentMain?.name}" (ID: ${currentMain?.id})`);

  if (currentMain?.id == TARGET_THEME_ID) {
    console.log(`Theme ${TARGET_THEME_ID} is already published as main!`);
  } else {
    // Step 2: Publish Theme by setting role: "main"
    console.log(`\nStep 2: Publishing Theme ${TARGET_THEME_ID} to role: "main"...`);
    const pubUrl = `https://${SHOP}/admin/api/${API_VERSION}/themes/${TARGET_THEME_ID}.json`;
    const pubRes = await fetch(pubUrl, {
      method: 'PUT',
      headers,
      body: JSON.stringify({
        theme: {
          role: 'main'
        }
      })
    });
    const pubData = await pubRes.json();

    if (!pubData.theme || pubData.errors) {
      console.error('[CRITICAL ERROR] Failed to publish theme:', pubData.errors);
      process.exit(1);
    }
    console.log(`[SUCCESS] Theme updated: "${pubData.theme.name}" (ID: ${pubData.theme.id}) is now role: "${pubData.theme.role}"!`);
  }

  // Step 3: Verify themes list
  console.log('\nStep 3: Verifying themes list post-publish...');
  const postRes = await fetch(`https://${SHOP}/admin/api/${API_VERSION}/themes.json`, { headers });
  const postData = await postRes.json();
  const newMain = postData.themes.find(t => t.role === 'main');
  const oldMain = postData.themes.find(t => t.id == PREVIOUS_LIVE_ID);

  console.log(`Active Live Theme (main): "${newMain?.name}" (ID: ${newMain?.id})`);
  console.log(`Preserved Backup Theme: "${oldMain?.name}" (ID: ${oldMain?.id}, Role: "${oldMain?.role}")`);

  // Step 4: Live Storefront Verification (NO PREVIEW PARAMETER)
  console.log('\nStep 4: Live Storefront Verification (Direct Production URL, no preview parameter)...');
  const liveUrls = [
    { label: 'Live Homepage', url: 'https://tryzavelyn.com/' },
    { label: 'Live Universal PDP', url: 'https://tryzavelyn.com/products/zavelyn-sensory-floor-mats' },
    { label: 'Live Hero Handpan PDP', url: 'https://tryzavelyn.com/products/zavelyn-handpan-master' },
    { label: 'Live Handpans Collection', url: 'https://tryzavelyn.com/collections/zavelyn-handpans' }
  ];

  const verificationResults = [];

  for (const item of liveUrls) {
    try {
      const liveRes = await fetch(item.url, {
        headers: {
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) Zavelyn-Live-Validator/2.0'
        }
      });
      const html = await liveRes.text();
      const hasElixirCss = html.includes('zavelyn-elixir') || html.includes('zavelyn');
      const hasProhibited = html.match(/\b(60[- ]day\s*(money[- ]back\s*)?guarantee|90[- ]day\s*(sound\s*)?guarantee|60[- ]night\s*risk[- ]free\s*trial)\b/gi);
      const has30Day = /30[- ]day/i.test(html);

      const check = {
        label: item.label,
        url: item.url,
        status: liveRes.status,
        htmlLength: html.length,
        hasZavelynThemeCode: hasElixirCss,
        has30DayGuarantee: has30Day,
        prohibitedMatches: hasProhibited ? [...new Set(hasProhibited)] : []
      };
      console.log(`[VERIFY ${liveRes.status == 200 ? 'PASS' : 'FAIL'}] ${item.label} (${item.url}):`);
      console.log(`  -> Status: ${liveRes.status} | Bytes: ${html.length} | Zavelyn 2.0 Code: ${hasElixirCss} | 30-Day: ${has30Day} | Prohibited: ${check.prohibitedMatches.length}`);
      verificationResults.push(check);
    } catch (err) {
      console.error(`Error verifying ${item.url}:`, err.message);
    }
  }

  const manifest = {
    publishTimestamp: new Date().toISOString(),
    publishedTheme: newMain,
    preservedTheme: oldMain,
    liveVerifications: verificationResults
  };

  fs.writeFileSync('scripts/live_publish_manifest.json', JSON.stringify(manifest, null, 2));
  console.log('\nPublish manifest saved to scripts/live_publish_manifest.json');
}

publishTheme();

import { getAccessToken, SHOP, API_VERSION } from './batch1_config.mjs';

async function renameThemes() {
  const token = await getAccessToken();
  const headers = { 'X-Shopify-Access-Token': token, 'Content-Type': 'application/json' };

  // Rename new main to "Zavelyn 2.0"
  await fetch(`https://${SHOP}/admin/api/${API_VERSION}/themes/187597717689.json`, {
    method: 'PUT',
    headers,
    body: JSON.stringify({ theme: { name: 'Zavelyn 2.0' } })
  });

  // Rename old main to "Zavelyn (Pre-Publish Backup)"
  await fetch(`https://${SHOP}/admin/api/${API_VERSION}/themes/186607567033.json`, {
    method: 'PUT',
    headers,
    body: JSON.stringify({ theme: { name: 'Zavelyn (Pre-Publish Backup)' } })
  });

  const res = await fetch(`https://${SHOP}/admin/api/${API_VERSION}/themes.json`, { headers });
  const data = await res.json();
  console.log('Updated Themes in Shopify Admin:');
  for (const t of data.themes) {
    console.log(`- ID: ${t.id} | Name: "${t.name}" | Role: "${t.role}"`);
  }
}

renameThemes();

async function testLiveStorefront() {
  const res = await fetch('https://tryzavelyn.com/', {
    headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36' }
  });
  const html = await res.text();
  console.log('HTTP Status:', res.status);
  console.log('HTML Length:', html.length);

  const titleMatch = html.match(/<title>(.*?)<\/title>/i);
  console.log('Page Title:', titleMatch ? titleMatch[1] : 'N/A');

  const announcementMatch = html.match(/class="[^"]*announcement[^"]*"[^>]*>(.*?)<\/div>/is) || html.match(/FREE US SHIPPING OVER \$49/i);
  console.log('Announcement Bar Found:', !!announcementMatch);

  const cartDrawerMatch = html.includes('willa-cart-drawer') || html.includes('cart-drawer');
  console.log('Cart Drawer Present:', cartDrawerMatch);

  const 30DayMatch = html.includes('30-Day Money-Back Guarantee') || html.includes('30-Day');
  console.log('30-Day Guarantee Found:', 30DayMatch);

  const prohibited = html.match(/\b(60[- ]day\s*(money[- ]back\s*)?guarantee|90[- ]day\s*(sound\s*)?guarantee|60[- ]night\s*risk[- ]free\s*trial)\b/gi);
  console.log('Prohibited Claims Count:', prohibited ? prohibited.length : 0);
}

testLiveStorefront();

