import fs from 'fs';
import { getAccessToken, SHOP, API_VERSION } from './batch1_config.mjs';

async function inspectProductAndStore() {
  const token = await getAccessToken();
  const headers = {
    'X-Shopify-Access-Token': token,
    'Content-Type': 'application/json'
  };

  console.log('=== STEP 1: CHECKING THEMES IN SHOPIFY ADMIN ===');
  const themesRes = await fetch(`https://${SHOP}/admin/api/${API_VERSION}/themes.json`, { headers });
  const themesData = await themesRes.json();
  for (const t of themesData.themes) {
    console.log(`Theme: ID=${t.id} | Name="${t.name}" | Role="${t.role}"`);
  }

  console.log('\n=== STEP 2: CHECKING TARGET PRODUCT DATA ===');
  const handle = 'zavelyn-botanaroots-organic-batana-hair-growth-oil';
  const query = `
    query getProduct($handle: String!) {
      productByHandle(handle: $handle) {
        id
        title
        handle
        status
        templateSuffix
        vendor
        productType
        totalInventory
        options {
          id
          name
          values
        }
        variants(first: 50) {
          nodes {
            id
            title
            sku
            price
            compareAtPrice
            inventoryQuantity
            availableForSale
            selectedOptions {
              name
              value
            }
          }
        }
      }
    }
  `;

  const gqlRes = await fetch(`https://${SHOP}/admin/api/${API_VERSION}/graphql.json`, {
    method: 'POST',
    headers,
    body: JSON.stringify({ query, variables: { handle } })
  });
  const gqlData = await gqlRes.json();
  const prod = gqlData.data?.productByHandle;
  console.log('Product Info:', JSON.stringify(prod, null, 2));

  console.log('\n=== STEP 3: CHECKING DISCOUNTS & APPS ===');
  const discQuery = `
    query {
      discountNodes(first: 20) {
        nodes {
          id
          discount {
            __typename
            ... on DiscountAutomaticApp {
              title
              status
            }
            ... on DiscountAutomaticBasic {
              title
              status
            }
            ... on DiscountAutomaticBxgy {
              title
              status
            }
            ... on DiscountAutomaticFreeShipping {
              title
              status
            }
            ... on DiscountCodeBasic {
              title
              status
            }
          }
        }
      }
    }
  `;
  const discRes = await fetch(`https://${SHOP}/admin/api/${API_VERSION}/graphql.json`, {
    method: 'POST',
    headers,
    body: JSON.stringify({ query: discQuery })
  });
  const discData = await discRes.json();
  console.log('Discounts count:', discData.data?.discountNodes?.nodes?.length);
  for (const d of (discData.data?.discountNodes?.nodes || [])) {
    console.log('Discount:', JSON.stringify(d));
  }

  fs.writeFileSync('scripts/botanaroots_backend_audit.json', JSON.stringify({
    themes: themesData.themes,
    product: prod,
    discounts: discData.data?.discountNodes?.nodes
  }, null, 2));
}

inspectProductAndStore();

