  console.log('HTML status:', res.status, 'Length:', html.length);

  // Look for bundle container or form in PDP
  const formMatch = html.match(/<form[^>]*action="\/cart\/add"[^>]*>([\s\S]*?)<\/form>/i);
  if (formMatch) {
    console.log('Found /cart/add form (length:', formMatch[0].length, ')');
