from PIL import Image
import numpy as np
from collections import deque

def flood_fill_transparency(img_path, out_path, bg_target=None, tolerance=22):
    im = Image.open(img_path).convert('RGBA')
    w, h = im.size
    arr = np.array(im)
    rgb = arr[:, :, :3].astype(np.float32)

    if bg_target is None:
        bg_target = rgb[0, 0]
    else:
        bg_target = np.array(bg_target, dtype=np.float32)

    diff = np.sqrt(np.sum((rgb - bg_target) ** 2, axis=2))

    # We will do a breadth-first search from border pixels where diff < tolerance
    visited = np.zeros((h, w), dtype=bool)
    queue = deque()

    # Add border pixels
    for x in range(w):
        for y in [0, h - 1]:
            if diff[y, x] <= tolerance:
                queue.append((y, x))
                visited[y, x] = True
    for y in range(h):
        for x in [0, w - 1]:
            if not visited[y, x] and diff[y, x] <= tolerance:
                queue.append((y, x))
                visited[y, x] = True

    while queue:
        cy, cx = queue.popleft()
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ny, nx = cy + dy, cx + dx
            if 0 <= ny < h and 0 <= nx < w and not visited[ny, nx]:
                # if it's close to background
                if diff[ny, nx] <= tolerance:
                    visited[ny, nx] = True
                    queue.append((ny, nx))

    # Now visited pixels are outer background
    # Set visited alpha with smooth feathering
    alpha = arr[:, :, 3].astype(np.float32)
    for y in range(h):
        for x in range(w):
            if visited[y, x]:
                # feather based on diff
                d = diff[y, x]
                if d < tolerance * 0.6:
                    alpha[y, x] = 0
                else:
                    alpha[y, x] = ((d - tolerance * 0.6) / (tolerance * 0.4)) * 255.0

    arr[:, :, 3] = np.clip(alpha, 0, 255).astype(np.uint8)
    out_im = Image.fromarray(arr)
    out_im.save(out_path, 'WEBP', quality=95)
    print(f'Saved {out_path}')

