import fs from 'fs';
import { spawn } from 'child_process';

const ARTIFACT_DIR = 'C:/Users/Admin/.gemini/antigravity-ide/brain/d0f634e2-c9dd-4bad-bdb2-3c956abea303';
const QA_IMG_DIR = 'assets/botanaroots_qa';
const THEME_ID = '187702804665';
const PREVIEW_ROOT = `https://tryzavelyn.com/?preview_theme_id=${THEME_ID}`;
const PDP_URL = `https://tryzavelyn.com/products/zavelyn-botanaroots-organic-batana-hair-growth-oil?preview_theme_id=${THEME_ID}`;
const PORT = 9238;

if (!fs.existsSync(QA_IMG_DIR)) {
  fs.mkdirSync(QA_IMG_DIR, { recursive: true });
}

async function getPreviewCookie() {
  const initRes = await fetch(PREVIEW_ROOT, { redirect: 'manual' });
  const rawCookies = initRes.headers.getSetCookie ? initRes.headers.getSetCookie() : [initRes.headers.get('set-cookie')];
  const essentialCookie = rawCookies.find(c => c && c.startsWith('_shopify_essential='));
  if (essentialCookie) {
    return essentialCookie.split(';')[0].replace('_shopify_essential=', '');
  }
  return null;
}

async function main() {
  console.log('========================================================================');
  console.log('BOTANAROOTS BUNDLE & UPSELL AUTOMATED QA & SCREENSHOT HARNESS');
  console.log('========================================================================\n');

  const cookieVal = await getPreviewCookie();
  console.log('Got preview cookie:', cookieVal ? 'YES' : 'NO');

  const userDataDir = `${process.env.TEMP}\\chrome-botana-qa-${Date.now()}`;
  console.log(`Launching dedicated Chrome on port ${PORT}...`);
  const chromeProc = spawn('C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe', [
    `--remote-debugging-port=${PORT}`,
    `--user-data-dir=${userDataDir}`,
    '--headless=new',
    '--disable-gpu',
    '--window-size=1440,1200',
    'about:blank'
  ]);

  let tabs = null;
  for (let i = 0; i < 20; i++) {
    await new Promise(r => setTimeout(r, 500));
    try {
      const res = await fetch(`http://127.0.0.1:${PORT}/json`);
      tabs = await res.json();
      if (tabs && tabs.length > 0) break;
    } catch (e) {}
  }

  if (!tabs) {
    chromeProc.kill();
    throw new Error(`Could not connect to Chrome on port ${PORT}`);
  }

  // TARGET REAL PAGE TAB (ignore extension background pages)
  const tab = tabs.find(t => t.type === 'page') || tabs[0];
  console.log(`Connected to CDP page tab: ${tab.url} (id: ${tab.id})`);

  const ws = new WebSocket(tab.webSocketDebuggerUrl);

  let msgId = 1;
  function send(method, params = {}) {
    return new Promise((resolve, reject) => {
      const curId = msgId++;
      const handler = (evt) => {
        const msg = JSON.parse(evt.data.toString());
        if (msg.id === curId) {
          ws.removeEventListener('message', handler);
          if (msg.error) reject(msg.error);
          else resolve(msg.result);
        }
      };
      ws.addEventListener('message', handler);
      ws.send(JSON.stringify({ id: curId, method, params }));
    });
  }

  await new Promise(r => ws.addEventListener('open', r));
  await send('Network.enable');

  if (cookieVal) {
    await send('Network.setCookie', {
      name: '_shopify_essential',
      value: cookieVal,
      domain: 'tryzavelyn.com',
      path: '/',
      secure: true,
      httpOnly: true
    });
    console.log('✔ Injected _shopify_essential cookie');
  }

  console.log(`Navigating to ${PDP_URL}...`);
  await send('Page.navigate', { url: PDP_URL });
  await new Promise(r => setTimeout(r, 7000));

  // Helper to capture full or clip screenshot
  async function captureShot(filename, clip = null) {
    const params = { format: 'png' };
    if (clip) params.clip = clip;
    const shot = await send('Page.captureScreenshot', params);
    const buf = Buffer.from(shot.data, 'base64');
    fs.writeFileSync(`${QA_IMG_DIR}/${filename}`, buf);
    fs.writeFileSync(`${ARTIFACT_DIR}/${filename}`, buf);
    console.log(`📸 Saved screenshot: ${filename} (${Math.round(buf.length / 1024)} KB)`);
  }

  // Helper to get element bounding box
  async function getBoundingBox(selector) {
    const res = await send('Runtime.evaluate', {
      expression: `(() => {
        const el = document.querySelector('${selector}');
        if (!el) return null;
        el.scrollIntoView({ behavior: 'instant', block: 'center' });
        const r = el.getBoundingClientRect();
        return { x: Math.max(0, r.x), y: Math.max(0, r.y), width: r.width, height: r.height };
      })()`,
      returnByValue: true
    });
    return res.result?.value;
  }

  // Wait until element is rendered
  const isReady = await send('Runtime.evaluate', {
    expression: `!!document.getElementById('zvBotanaBundleComponent')`,
    returnByValue: true
  });
  console.log('zvBotanaBundleComponent present:', isReady.result?.value);

  // Set default mockup state: Buy 3 selected, 120ml active ($125.99)
  await send('Runtime.evaluate', {
    expression: `(() => {
      const card3 = document.querySelector('#zvCardBuy3');
      if (card3 && !card3.classList.contains('selected')) card3.click();
      const upsell = document.querySelector('#zvUpsellCard');
      if (upsell && !upsell.classList.contains('active')) upsell.click();
    })()`
  });
  await new Promise(r => setTimeout(r, 800));

  // =========================================================================
  // 1. DESKTOP 1440px QA
  // =========================================================================
  console.log('\n--- 1. DESKTOP 1440px QA ---');
  await send('Emulation.setDeviceMetricsOverride', {
    width: 1440,
    height: 1200,
    deviceScaleFactor: 1,
    mobile: false
  });
  await new Promise(r => setTimeout(r, 1000));
  let box = await getBoundingBox('#zvBotanaBundleComponent');
  if (box) {
    const clip = {
      x: Math.max(0, box.x - 20),
      y: Math.max(0, box.y - 15),
      width: Math.min(1440, box.width + 40),
      height: box.height + 30,
      scale: 1
    };
    await captureShot('botana_bundle_desktop_1440.png', clip);
  }

  // =========================================================================
  // 2. TABLET 768px QA
  // =========================================================================
  console.log('\n--- 2. TABLET 768px QA ---');
  await send('Emulation.setDeviceMetricsOverride', {
    width: 768,
    height: 1024,
    deviceScaleFactor: 1,
    mobile: false
  });
  await new Promise(r => setTimeout(r, 1000));
  box = await getBoundingBox('#zvBotanaBundleComponent');
  if (box) {
    const clip = {
      x: Math.max(0, box.x - 15),
      y: Math.max(0, box.y - 15),
      width: Math.min(768, box.width + 30),
      height: box.height + 30,
      scale: 1
    };
    await captureShot('botana_bundle_tablet_768.png', clip);
  }

  // =========================================================================
  // 3. MOBILE 390px QA (iPhone 12/13/14)
  // =========================================================================
  console.log('\n--- 3. MOBILE 390px QA ---');
  await send('Emulation.setDeviceMetricsOverride', {
    width: 390,
    height: 844,
    deviceScaleFactor: 2,
    mobile: true
  });
  await new Promise(r => setTimeout(r, 1000));
  box = await getBoundingBox('#zvBotanaBundleComponent');
  if (box) {
    const clip = {
      x: 0,
      y: Math.max(0, box.y - 10),
      width: 390,
      height: box.height + 20,
      scale: 1
    };
    await captureShot('botana_bundle_mobile_390.png', clip);
  }

  // =========================================================================
  // 4. MOBILE 375px QA (iPhone SE / Standard Narrow)
  // =========================================================================
  console.log('\n--- 4. MOBILE 375px QA ---');
  await send('Emulation.setDeviceMetricsOverride', {
    width: 375,
    height: 812,
    deviceScaleFactor: 2,
    mobile: true
  });
  await new Promise(r => setTimeout(r, 1000));
  box = await getBoundingBox('#zvBotanaBundleComponent');
  if (box) {
    const clip = {
      x: 0,
      y: Math.max(0, box.y - 10),
      width: 375,
      height: box.height + 20,
      scale: 1
    };
    await captureShot('botana_bundle_mobile_375.png', clip);
  }

  // Reset to desktop for combination testing
  await send('Emulation.setDeviceMetricsOverride', {
    width: 1440,
    height: 1200,
    deviceScaleFactor: 1,
    mobile: false
  });
  await new Promise(r => setTimeout(r, 800));

  // =========================================================================
  // 5. COMBINATIONS TEST (6-Combination QA Matrix)
  // =========================================================================
  console.log('\n--- 5. TESTING 6 COMBINATIONS MATRIX ---');
  const combinations = [
    { bundle: 1, upgraded: false, expectedTotal: '$39.99', expectedUnit: '$39.99 / bottle', label: 'Buy 1 / 60ml' },
    { bundle: 1, upgraded: true, expectedTotal: '$49.99', expectedUnit: '$49.99 / bottle', label: 'Buy 1 / 120ml' },
    { bundle: 2, upgraded: false, expectedTotal: '$79.98', expectedUnit: '$39.99 / bottle', label: 'Buy 2 / 60ml' },
    { bundle: 2, upgraded: true, expectedTotal: '$99.98', expectedUnit: '$49.99 / bottle', label: 'Buy 2 / 120ml' },
    { bundle: 3, upgraded: false, expectedTotal: '$95.99', expectedUnit: '$32.00 / bottle', label: 'Buy 3 / 60ml' },
    { bundle: 3, upgraded: true, expectedTotal: '$125.99', expectedUnit: '$42.00 / bottle', label: 'Buy 3 / 120ml' }
  ];

  const results = [];
  for (const comb of combinations) {
    const evalRes = await send('Runtime.evaluate', {
      expression: `(() => {
        // Set bundle
        const card = document.querySelector('#zvCardBuy${comb.bundle}');
        if (card) card.click();

        // Set upgrade
        const upsell = document.querySelector('#zvUpsellCard');
        const isActive = upsell && upsell.classList.contains('active');
        if (isActive !== ${comb.upgraded}) {
          upsell.click();
        }

        const pkgVal = document.querySelector('#zvSummaryPackage')?.textContent?.trim();
        const totVal = document.querySelector('#zvSummaryTotal')?.textContent?.trim();
        const unitVal = document.querySelector('#zvSummaryUnitPill')?.textContent?.trim();
        const ctaVal = document.querySelector('#zvCtaPrice')?.textContent?.trim();
        const deltaVal = document.querySelector('#zvUpsellDelta')?.textContent?.trim();
        const shipVal = document.querySelector('#zvShippingText')?.textContent?.trim();

        return {
          packageText: pkgVal,
          totalPrice: totVal,
          unitPrice: unitVal,
          ctaPrice: ctaVal,
          upsellDelta: deltaVal,
          shippingText: shipVal
        };
      })()`,
      returnByValue: true
    });

    const val = evalRes.result?.value || {};
    const pass = (val.totalPrice === comb.expectedTotal && val.unitPrice === comb.expectedUnit && val.ctaPrice === comb.expectedTotal);
    results.push({
      ...comb,
      actual: val,
      status: pass ? 'PASS' : 'FAIL'
    });
    console.log(`[${pass ? 'PASS' : 'FAIL'}] ${comb.label}: Total=${val.totalPrice} | Unit=${val.unitPrice} | CTA=${val.ctaPrice} | Pkg=${val.packageText}`);
  }

  // =========================================================================
  // 6. MODAL & PREVIEW GUARDRAIL TEST (120ml Upgrade)
  // =========================================================================
  console.log('\n--- 6. TESTING 120ml UPGRADE NOTICE MODAL ---');
  const modalTest = await send('Runtime.evaluate', {
    expression: `(() => {
      // Ensure 120ml is active
      const upsell = document.querySelector('#zvUpsellCard');
      if (upsell && !upsell.classList.contains('active')) upsell.click();

      const btn = document.querySelector('#zvBotanaCtaBtn');
      if (btn) btn.click();

      const modal = document.querySelector('#zvPreviewModal');
      const isVisible = modal && modal.style.display === 'flex';
      const msg = document.querySelector('#zvModalMsg')?.textContent?.trim();

      // Close modal
      const closeBtn = document.querySelector('#zvModalClose');
      if (closeBtn) closeBtn.click();

      return { modalVisible: isVisible, message: msg };
    })()`,
    returnByValue: true
  });
  console.log('120ml Modal Result:', JSON.stringify(modalTest.result?.value, null, 2));

  // =========================================================================
  // 7. AJAX CART & CART DRAWER TEST (60ml Live Variant)
  // =========================================================================
  console.log('\n--- 7. TESTING AJAX CART ADD & CART DRAWER ---');
  const cartTest = await send('Runtime.evaluate', {
    expression: `(async () => {
      // Ensure 60ml is active
      const upsell = document.querySelector('#zvUpsellCard');
      if (upsell && upsell.classList.contains('active')) upsell.click();

      const card3 = document.querySelector('#zvCardBuy3');
      if (card3) card3.click();

      const btn = document.querySelector('#zvBotanaCtaBtn');
      if (btn) btn.click();

      // Wait for ajax response
      await new Promise(r => setTimeout(r, 2500));

      const drawer = document.querySelector('#willaCartDrawer');
      const isOpen = drawer && drawer.classList.contains('active');
      const drawerCount = document.querySelector('#willaDrawerCount')?.textContent?.trim();

      return {
        drawerActive: isOpen,
        drawerCount: drawerCount
      };
    })()`,
    awaitPromise: true,
    returnByValue: true
  });
  console.log('Cart Drawer Add Test:', JSON.stringify(cartTest.result?.value, null, 2));

  // Capture cart drawer screenshot
  await new Promise(r => setTimeout(r, 1000));
  await captureShot('botana_cart_drawer_opened.png');

  // Save QA Report JSON
  fs.writeFileSync('scripts/botanaroots_qa_matrix_results.json', JSON.stringify({
    timestamp: new Date().toISOString(),
    themeId: THEME_ID,
    results: results,
    modalTest: modalTest.result?.value,
    cartTest: cartTest.result?.value
  }, null, 2));
  console.log('\nSaved scripts/botanaroots_qa_matrix_results.json');

  chromeProc.kill();
  console.log('\nQA complete. Chrome closed successfully.');
}

main().catch(err => {
  console.error('QA Harness Error:', err);
  process.exit(1);
});

