args.CodeContent:
import { spawn } from 'child_process';

const PORT = 9260;
const chromeProc = spawn('C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe', [
  `--remote-debugging-port=${PORT}`,
  `--user-data-dir=${process.env.TEMP}\\chrome-check-${Date.now()}`,
  '--headless=new',
  '--disable-gpu',
  'about:blank'
]);

async function run() {
  await new Promise(r => setTimeout(r, 1500));
  const res = await fetch(`http://127.0.0.1:${PORT}/json`);
  const tabs = await res.json();
  const ws = new WebSocket(tabs[0].webSocketDebuggerUrl);
  await new Promise(r => ws.addEventListener('open', r));

  let msgId = 1;
  function send(method, params = {}) {
    return new Promise((resolve, reject) => {
      const curId = msgId++;
      const handler = (evt) => {
        const msg = JSON.parse(evt.data.toString());
        if (msg.id === curId) {
          ws.removeEventListener('message', handler);
          resolve(msg.result);
        }
      };
      ws.addEventListener('message', handler);
      ws.send(JSON.stringify({ id: curId, method, params }));
    });
  }

  await send('Page.navigate', { url: 'https://tryzavelyn.com/products/zavelyn-botanaroots-organic-batana-hair-growth-oil' });
  await new Promise(r => setTimeout(r, 6000));

  const evalRes = await send('Runtime.evaluate', {
    expression: `(() => {
      return {
        hasExtendedFaq: !!document.querySelector('#zv-extended-faq'),
        extendedFaqItems: document.querySelectorAll('#zv-extended-faq .zv-faq-item').length,
        hasShortFaq: !!document.querySelector('.kc-faq'),
        shortFaqItems: document.querySelectorAll('.kc-faq details').length,
        shortFaqOpenCount: document.querySelectorAll('.kc-faq details[open]').length,
        trustCardCount: document.querySelectorAll('.kc-trust .kc-trust__chip').length,
        sections: Array.from(document.querySelectorAll('[id^="shopify-section-"]')).map(s => s.id)
      };
    })()`,
    returnByValue: true
  });

  console.log('DOM check:', evalRes.result?.value);
  chromeProc.kill();
}

run().catch(err => {
  console.error(err);
  chromeProc.kill();
});

