                    <summary class="kc-faq__q">
                      <span>{{ block.settings.question }}</span>
                    </summary>
                    <div class="kc-faq__a">
                      <p>{{ block.settings.answer }}</p>
                    </div>
                  </details>
                {%- endfor -%}
              {%- else -%}
