              {%- endif -%}
            </div>
          {%- else -%}
            ${originalFaqHtml.replace('<!-- SHORT FAQ ACCORDIONS (.kc-faq) - END OF BUY BOX -->\n', '')}
          {%- endif -%}\n          `;

// Replace trust & faq blocks
