      const bodyImages = Array.from(document.querySelectorAll('#zv-product-description img')).map(img => ({
        src: img.src,
        alt: img.alt,
        width: img.offsetWidth,
        height: img.offsetHeight
      }));

      return {
        url: window.location.href,
        title: document.title,
