/* ==========================================================================
   ZAVELYN vFIT — SELF-CARE UPSELL SUITE (VERSION A & B)
   Style: Premium Feminine Wellness & Clean American DTC
   Color Palette: Soft Blush Pink, Warm Ivory, Forest Green, Deep Charcoal
   ========================================================================== */

:root {
  --zv-font: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --zv-bg-page: #FAF9F8;
  --zv-bg-white: #FFFFFF;
  --zv-bg-blush: #FCF7F6;
  --zv-bg-blush-light: #FFF9F8;
  --zv-bg-warm-ivory: #FAF6F3;
  --zv-border-subtle: #EFE8E6;
  --zv-border-active: #C86D61;
  --zv-border-active-soft: rgba(200, 109, 97, 0.25);
  --zv-color-text-main: #1A202C;
  --zv-color-text-muted: #64748B;
  --zv-color-text-subtle: #94A3B8;
  --zv-color-rose: #C86D61;
  --zv-color-rose-dark: #A34A3E;
  --zv-color-rose-pill: #F7EBE8;
  --zv-color-forest: #234E3E;
  --zv-color-forest-dark: #193B2E;
  --zv-color-forest-pill: #EBF4F0;
  --zv-color-gold: #D97706;
  --zv-shadow-card: 0 4px 20px rgba(160, 120, 110, 0.08);
  --zv-shadow-card-hover: 0 10px 30px rgba(160, 120, 110, 0.14);
  --zv-shadow-selected: 0 8px 28px rgba(200, 109, 97, 0.16);
  --zv-radius-card: 16px;
  --zv-radius-pill: 9999px;
  --zv-radius-btn: 12px;
  --zv-transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Prototype Control Bar (Fixed Top Switcher) */
.proto-control-bar {
  position: sticky;
  top: 0;
  z-index: 9999;
  background: #111827;
  color: #FFFFFF;
  padding: 12px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.25);
  font-family: var(--zv-font);
}
.proto-control-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #FBBF24;
}
.proto-control-badge::before {
  content: '';
  display: inline-block;
  width: 8px;
  height: 8px;
  background: #10B981;
  border-radius: 50%;
  box-shadow: 0 0 10px #10B981;
}
.proto-switch-group {
  display: flex;
  background: rgba(255, 255, 255, 0.12);
  border-radius: 999px;
  padding: 3px;
  gap: 4px;
}
.proto-switch-btn {
  border: none;
  background: transparent;
  color: #D1D5DB;
  font-size: 13px;
  font-weight: 600;
  padding: 6px 16px;
  border-radius: 999px;
  cursor: pointer;
  transition: var(--zv-transition);
  font-family: inherit;
}
.proto-switch-btn.active {
  background: #FFFFFF;
  color: #111827;
  box-shadow: 0 2px 8px rgba(0,0,0,0.2);
}
.proto-state-indicator {
  font-size: 12px;
  color: #9CA3AF;
  display: flex;
  align-items: center;
  gap: 8px;
}
.proto-state-indicator strong {
  color: #F9FAFB;
}

/* ==========================================================================
   SELF-CARE UPSELL SECTION WRAPPER
   ========================================================================== */
.zv-selfcare-section {
  background: var(--zv-bg-blush);
  border-top: 1px solid var(--zv-border-subtle);
  border-bottom: 1px solid var(--zv-border-subtle);
  padding: 56px 0 64px;
  font-family: var(--zv-font);
  position: relative;
  overflow: hidden;
}
.zv-selfcare-section::before {
  content: '';
  position: absolute;
  top: -120px;
  right: -100px;
  width: 380px;
  height: 380px;
  background: radial-gradient(circle, rgba(200, 109, 97, 0.08) 0%, rgba(252, 247, 246, 0) 70%);
  border-radius: 50%;
  pointer-events: none;
}
.zv-selfcare-section::after {
  content: '';
  position: absolute;
  bottom: -100px;
  left: -80px;
  width: 320px;
  height: 320px;
  background: radial-gradient(circle, rgba(46, 74, 62, 0.05) 0%, rgba(252, 247, 246, 0) 70%);
  border-radius: 50%;
  pointer-events: none;
}
.zv-selfcare-container {
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 24px;
  position: relative;
  z-index: 1;
}

/* Section Header */
.zv-selfcare-header {
  text-align: center;
  max-width: 720px;
  margin: 0 auto 36px;
}
.zv-selfcare-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--zv-color-rose-pill);
  color: var(--zv-color-rose-dark);
  font-size: 11.5px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 5px 14px;
  border-radius: var(--zv-radius-pill);
  margin-bottom: 12px;
  border: 1px solid rgba(200, 109, 97, 0.2);
}
.zv-selfcare-title {
  font-size: 30px;
  font-weight: 800;
  color: var(--zv-color-text-main);
  margin: 0 0 10px;
  line-height: 1.25;
  letter-spacing: -0.02em;
}
.zv-selfcare-sub {
  font-size: 15.5px;
  color: var(--zv-color-text-muted);
  line-height: 1.6;
  margin: 0;
}

/* ==========================================================================
   VERSION A — PREMIUM PRODUCT CARDS (SIDE-BY-SIDE)
   ========================================================================== */
.zv-cards-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  margin-bottom: 32px;
}

.zv-addon-card {
  background: var(--zv-bg-white);
  border: 2px solid var(--zv-border-subtle);
  border-radius: var(--zv-radius-card);
  padding: 24px;
  display: flex;
  flex-direction: column;
  transition: var(--zv-transition);
  position: relative;
  cursor: pointer;
  box-shadow: var(--zv-shadow-card);
}
.zv-addon-card:hover {
  transform: translateY(-3px);
  border-color: rgba(200, 109, 97, 0.4);
  box-shadow: var(--zv-shadow-card-hover);
}
.zv-addon-card.selected {
  border-color: var(--zv-border-active);
  background: var(--zv-bg-blush-light);
  box-shadow: var(--zv-shadow-selected);
}

/* Card Selection Checkmark Ribbon */
.zv-card-status-pill {
  position: absolute;
  top: 18px;
  right: 18px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  border-radius: var(--zv-radius-pill);
  font-size: 12px;
  font-weight: 750;
  letter-spacing: 0.02em;
  transition: var(--zv-transition);
  background: #F1F5F9;
  color: var(--zv-color-text-muted);
  border: 1px solid #E2E8F0;
  z-index: 2;
}
.zv-addon-card.selected .zv-card-status-pill {
  background: var(--zv-color-forest);
  color: #FFFFFF;
  border-color: var(--zv-color-forest);
  box-shadow: 0 2px 10px rgba(35, 78, 62, 0.25);
}

/* Media Zone */
.zv-card-media-wrap {
  position: relative;
  width: 100%;
  height: 220px;
  background: #F9F9FA;
  border-radius: 12px;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
}
.zv-card-img {
  max-width: 85%;
  max-height: 85%;
  object-fit: contain;
  transition: transform 0.35s ease;
}
.zv-addon-card:hover .zv-card-img {
  transform: scale(1.05);
}
.zv-card-badge {
  position: absolute;
  bottom: 12px;
  left: 12px;
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(4px);
  color: var(--zv-color-forest);
  font-size: 11px;
  font-weight: 750;
  padding: 4px 10px;
  border-radius: var(--zv-radius-pill);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06);
  border: 1px solid #E2E8F0;
}

/* Card Content */
.zv-card-body {
  display: flex;
  flex-direction: column;
  flex: 1;
}
.zv-card-title {
  font-size: 18px;
  font-weight: 800;
  color: var(--zv-color-text-main);
  margin: 0 0 8px;
  line-height: 1.35;
}
.zv-card-desc {
  font-size: 13.5px;
  color: var(--zv-color-text-muted);
  line-height: 1.55;
  margin: 0 0 16px;
  flex: 1;
}

/* Price Row */
.zv-card-price-row {
  display: flex;
  align-items: baseline;
  gap: 10px;
  margin-bottom: 18px;
  padding-top: 14px;
  border-top: 1px solid var(--zv-border-subtle);
}
.zv-card-price-current {
  font-size: 22px;
  font-weight: 800;
  color: var(--zv-color-text-main);
}
.zv-card-price-compare {
  font-size: 14.5px;
  color: var(--zv-color-text-subtle);
  text-decoration: line-through;
}
.zv-card-save-pill {
  font-size: 11.5px;
  font-weight: 750;
  background: var(--zv-color-forest-pill);
  color: var(--zv-color-forest);
  padding: 3px 8px;
  border-radius: var(--zv-radius-pill);
  border: 1px solid rgba(35, 78, 62, 0.15);
}

/* Action Area */
.zv-card-action-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.zv-card-checkbox-label {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 14px;
  font-weight: 700;
  color: var(--zv-color-text-main);
  user-select: none;
  cursor: pointer;
}
.zv-custom-check {
  width: 22px;
  height: 22px;
  border: 2px solid #CBD5E1;
  border-radius: 6px;
  background: #FFFFFF;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: var(--zv-transition);
  color: transparent;
}
.zv-addon-card.selected .zv-custom-check {
  background: var(--zv-color-forest);
  border-color: var(--zv-color-forest);
  color: #FFFFFF;
}
.zv-link-details {
  font-size: 13px;
  color: var(--zv-color-rose-dark);
  font-weight: 600;
  text-decoration: none;
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 0;
  transition: var(--zv-transition);
  border-bottom: 1px dashed rgba(163, 74, 62, 0.4);
}
.zv-link-details:hover {
  color: #83271D;
  border-bottom-style: solid;
}

/* ==========================================================================
   VERSION B — COMPACT UPSELL ROWS (HORIZONTAL LIST)
   ========================================================================== */
.zv-rows-list {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 32px;
}

.zv-addon-row {
  background: var(--zv-bg-white);
  border: 2px solid var(--zv-border-subtle);
  border-radius: var(--zv-radius-card);
  padding: 18px 22px;
  display: flex;
  align-items: center;
  gap: 20px;
  transition: var(--zv-transition);
  cursor: pointer;
  box-shadow: var(--zv-shadow-card);
  position: relative;
}
.zv-addon-row:hover {
  border-color: rgba(200, 109, 97, 0.4);
  box-shadow: var(--zv-shadow-card-hover);
}
.zv-addon-row.selected {
  border-color: var(--zv-border-active);
  background: var(--zv-bg-blush-light);
  box-shadow: var(--zv-shadow-selected);
}

.zv-row-media {
  width: 104px;
  height: 104px;
  flex: 0 0 104px;
  background: #F9F9FA;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border: 1px solid #F1F5F9;
}
.zv-row-img {
  max-width: 88%;
  max-height: 88%;
  object-fit: contain;
  transition: transform 0.3s ease;
}
.zv-addon-row:hover .zv-row-img {
  transform: scale(1.06);
}

.zv-row-content {
  flex: 1;
  min-width: 0;
}
.zv-row-badge {
  display: inline-block;
  font-size: 10.5px;
  font-weight: 750;
  text-transform: uppercase;
  color: var(--zv-color-rose-dark);
  background: var(--zv-color-rose-pill);
  padding: 2px 8px;
  border-radius: var(--zv-radius-pill);
  margin-bottom: 4px;
}
.zv-row-title {
  font-size: 16.5px;
  font-weight: 800;
  color: var(--zv-color-text-main);
  margin: 0 0 4px;
  line-height: 1.3;
}
.zv-row-desc {
  font-size: 13px;
  color: var(--zv-color-text-muted);
  margin: 0 0 8px;
  line-height: 1.45;
}
.zv-row-price-area {
  display: flex;
  align-items: center;
  gap: 8px;
}
.zv-row-price-current {
  font-size: 18px;
  font-weight: 800;
  color: var(--zv-color-text-main);
}
.zv-row-price-compare {
  font-size: 13.5px;
  color: var(--zv-color-text-subtle);
  text-decoration: line-through;
}
.zv-row-save-pill {
  font-size: 11px;
  font-weight: 700;
  color: var(--zv-color-forest);
  background: var(--zv-color-forest-pill);
  padding: 2px 6px;
  border-radius: var(--zv-radius-pill);
}

/* Row Action Button / Checkbox */
.zv-row-action {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
}
.zv-row-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-width: 140px;
  height: 42px;
  padding: 0 16px;
  border-radius: var(--zv-radius-pill);
  font-size: 13.5px;
  font-weight: 750;
  border: 1.5px solid #CBD5E1;
  background: #FFFFFF;
  color: var(--zv-color-text-main);
  cursor: pointer;
  transition: var(--zv-transition);
  font-family: inherit;
}
.zv-addon-row.selected .zv-row-btn {
  background: var(--zv-color-forest);
  border-color: var(--zv-color-forest);
  color: #FFFFFF;
  box-shadow: 0 3px 12px rgba(35, 78, 62, 0.25);
}
.zv-addon-row:not(.selected) .zv-row-btn:hover {
  background: var(--zv-color-rose-pill);
  border-color: var(--zv-color-rose);
  color: var(--zv-color-rose-dark);
}

/* ==========================================================================
   DYNAMIC ORDER SUMMARY BOX — "YOUR SELF-CARE PACKAGE"
   ========================================================================== */
.zv-package-summary-card {
  background: var(--zv-bg-white);
  border: 2px solid #EAE1DE;
  border-radius: 18px;
  padding: 28px 32px;
  box-shadow: 0 8px 30px rgba(180, 140, 130, 0.1);
  position: relative;
  transition: var(--zv-transition);
}
.zv-summary-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--zv-border-subtle);
  padding-bottom: 16px;
  margin-bottom: 18px;
}
.zv-summary-title {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 14px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--zv-color-rose-dark);
  margin: 0;
}
.zv-summary-badge-tier {
  font-size: 11px;
  font-weight: 750;
  background: #F1F5F9;
  color: #475569;
  padding: 3px 10px;
  border-radius: var(--zv-radius-pill);
}

/* Items Breakdown */
.zv-summary-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 22px;
}
.zv-summary-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 14.5px;
  color: var(--zv-color-text-main);
  animation: zvFadeIn 0.3s ease;
}
.zv-summary-item-left {
  display: flex;
  align-items: center;
  gap: 10px;
}
.zv-item-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--zv-color-forest);
}
.zv-summary-item.base .zv-item-dot {
  background: var(--zv-color-rose);
}
.zv-item-name {
  font-weight: 600;
}
.zv-item-tag {
  font-size: 11px;
  font-weight: 700;
  color: var(--zv-color-rose-dark);
  background: var(--zv-color-rose-pill);
  padding: 2px 6px;
  border-radius: 4px;
}
.zv-item-price {
  font-weight: 750;
}

/* Total Section */
.zv-summary-total-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 0;
  border-top: 2px dashed #E2E8F0;
  margin-bottom: 20px;
}
.zv-total-label-wrap {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.zv-total-label {
  font-size: 16px;
  font-weight: 800;
  color: var(--zv-color-text-main);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.zv-total-savings {
  font-size: 13px;
  font-weight: 750;
  color: var(--zv-color-forest);
}
.zv-total-numbers {
  text-align: right;
}
.zv-total-price-large {
  font-size: 30px;
  font-weight: 900;
  color: var(--zv-color-text-main);
  line-height: 1.1;
  font-feature-settings: "tnum";
}
.zv-total-compare-strike {
  font-size: 15px;
  color: var(--zv-color-text-subtle);
  text-decoration: line-through;
  margin-top: 3px;
}

/* Master CTA Button */
.zv-package-cta-btn {
  width: 100%;
  height: 56px;
  background: #111827;
  color: #FFFFFF;
  border: none;
  border-radius: var(--zv-radius-btn);
  font-size: 16px;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  transition: var(--zv-transition);
  box-shadow: 0 4px 18px rgba(17, 24, 39, 0.25);
  font-family: inherit;
  position: relative;
  overflow: hidden;
}
.zv-package-cta-btn:hover {
  background: var(--zv-color-forest);
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(35, 78, 62, 0.3);
}
.zv-package-cta-btn:active {
  transform: translateY(0);
}
.zv-package-cta-btn .zv-cta-arrow {
  transition: transform 0.2s ease;
}
.zv-package-cta-btn:hover .zv-cta-arrow {
  transform: translateX(4px);
}

/* Trust Elements */
.zv-summary-trust-row {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 20px;
  margin-top: 18px;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--zv-color-text-muted);
}
.zv-trust-mini-item {
  display: flex;
