  background: #E2E8F0;
  color: #0F172A;
}

/* Toast Notification for Simulated Checkout */
.zv-toast-notification {
  position: fixed;
  bottom: 24px;
  right: 24px;
  background: #111827;
  color: #FFFFFF;
  padding: 16px 22px;
  border-radius: 12px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
  z-index: 999999;
  display: flex;
  align-items: flex-start;
  gap: 14px;
  max-width: 420px;
  font-family: var(--zv-font);
  transform: translateY(120%);
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  border-left: 4px solid #10B981;
}
.zv-toast-notification.active {
  transform: translateY(0);
}

@keyframes zvFadeIn {
  from { opacity: 0; transform: translateY(-4px); }
  to { opacity: 1; transform: translateY(0); }
