<script>
(function() {
  const DATA = {
    vfit: { id: {{ vfit_var_id }}, price: 249.99, compare: 450.00, title: 'Zavelyn vFit Red Light Wellness Device' },
    eye: { id: {{ eye_var_id }}, price: 89.99, compare: 149.99, title: 'Zavelyn Red Light Eye Care Mask' },
    face: { id: {{ face_var_id }}, price: 129.99, compare: 199.99, title: 'Zavelyn LED Red Light Face Mask' }
  };

  const state = {
    eyeSelected: false,
    faceSelected: false
  };

  function formatMoney(amount) {
    return '$' + amount.toFixed(2);
  }

  function recalculate() {
    let total = DATA.vfit.price;
    let compare = DATA.vfit.compare;
    let count = 0;

    if (state.eyeSelected) {
      total += DATA.eye.price;
      compare += DATA.eye.compare;
      count++;
    }
    if (state.faceSelected) {
      total += DATA.face.price;
      compare += DATA.face.compare;
      count++;
    }

    const savings = compare - total;

    // DOM Updates
    const cardEye = document.getElementById('zvCardEye');
    const cardFace = document.getElementById('zvCardFace');
    const pillEye = document.getElementById('pillEye');
    const pillFace = document.getElementById('pillFace');

    if (cardEye && pillEye) {
      if (state.eyeSelected) {
        cardEye.classList.add('selected');
        pillEye.textContent = '✓ ADDED';
      } else {
        cardEye.classList.remove('selected');
        pillEye.textContent = '+ ADD TO ORDER';
      }
    }

    if (cardFace && pillFace) {
      if (state.faceSelected) {
        cardFace.classList.add('selected');
        pillFace.textContent = '✓ ADDED';
      } else {
        cardFace.classList.remove('selected');
        pillFace.textContent = '+ ADD TO ORDER';
      }
    }

    const rowEye = document.getElementById('zvSummaryEye');
    const rowFace = document.getElementById('zvSummaryFace');
    if (rowEye) rowEye.style.display = state.eyeSelected ? 'flex' : 'none';
    if (rowFace) rowFace.style.display = state.faceSelected ? 'flex' : 'none';

    const tierBadge = document.getElementById('zvSummaryTierBadge');
    if (tierBadge) {
      if (count === 0) tierBadge.textContent = 'STANDARD SINGLE DEVICE';
      else if (count === 1) tierBadge.textContent = 'DUO SELF-CARE SUITE';
      else tierBadge.textContent = 'COMPLETE 3-PIECE REJUVENATION SUITE';
    }

    const totalEl = document.getElementById('zvSummaryTotal');
    const compareEl = document.getElementById('zvSummaryCompare');
    const savingsEl = document.getElementById('zvSummarySavings');
    const ctaLabel = document.getElementById('zvSelfCareCtaLabel');

    if (totalEl) totalEl.textContent = formatMoney(total);
    if (compareEl) compareEl.textContent = formatMoney(compare);
    if (savingsEl) savingsEl.textContent = 'YOU SAVE ' + formatMoney(savings) + ' (TOTAL BUNDLE DISCOUNT)';

    if (ctaLabel) {
      if (count === 0) ctaLabel.textContent = 'CLAIM vFIT WELLNESS DEVICE — ' + formatMoney(total);
      else ctaLabel.textContent = 'CLAIM YOUR SELF-CARE PACKAGE — ' + formatMoney(total);
    }
  }

  // Card click toggles
  document.getElementById('zvCardEye')?.addEventListener('click', function(e) {
    if (e.target.closest('.zv-link-details')) return;
    state.eyeSelected = !state.eyeSelected;
    recalculate();
  });

  document.getElementById('zvCardFace')?.addEventListener('click', function(e) {
    if (e.target.closest('.zv-link-details')) return;
    state.faceSelected = !state.faceSelected;
    recalculate();
  });

  // Batch Add to Cart Action
  document.getElementById('zvSelfCareCtaBtn')?.addEventListener('click', async function() {
    const btn = this;
    btn.classList.add('loading');

    const itemsToAdd = [
      { id: DATA.vfit.id, quantity: 1 }
    ];
    if (state.eyeSelected) itemsToAdd.push({ id: DATA.eye.id, quantity: 1 });
    if (state.faceSelected) itemsToAdd.push({ id: DATA.face.id, quantity: 1 });

    try {
      const res = await fetch('/cart/add.js', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ items: itemsToAdd })
      });
      if (!res.ok) throw new Error('Add to cart failed');

      // Refresh & open Willa or Zavelyn Cart Drawer
      if (typeof window.willaOpenCartDrawer === 'function') {
        if (typeof window.willaRefreshCart === 'function') await window.willaRefreshCart();
        window.willaOpenCartDrawer();
        return;
      }
      const directDrawer = document.getElementById('willaCartDrawer');
      const directOverlay = document.getElementById('willaCartOverlay');
      if (directDrawer) {
        directDrawer.classList.add('active');
        if (directOverlay) directOverlay.classList.add('active');
        if (typeof window.willaRefreshCart === 'function') await window.willaRefreshCart();
        return;
      }
      window.location.href = '/checkout';
    } catch(err) {
      console.error(err);
      alert('Could not add to bag. Please try again.');
    } finally {
      btn.classList.remove('loading');
    }
  });

  // Modal helpers exposed
  window.openVfitModal = function(key) {
    const modal = document.getElementById('zvSelfCareModal');
    const body = document.getElementById('zvSelfCareModalBody');
    if (!modal || !body) return;

    if (key === 'eyeMask') {
      body.innerHTML = '<h3 style="font-size: 20px; font-weight: 800; color: #1A202C; margin-top:0;">Zavelyn Red Light Eye Care Mask</h3>' +
        '<p style="color: #64748B; font-size: 14px; line-height: 1.6;">Precision 660nm red photon LEDs designed specifically for the delicate periorbital zone around the eyes.</p>' +
        '<ul style="color: #334155; font-size: 14px; line-height: 1.8; padding-left: 20px;">' +
        '<li><strong>Targeted Eye Contouring:</strong> Supports collagen synthesis and micro-circulation.</li>' +
        '<li><strong>Cushioned Silicone Rim:</strong> Soft blackout fit for evening relaxation.</li>' +
        '<li><strong>10-Min Timer:</strong> Hands-free safe session routine.</li>' +
        '<li><strong>USB-C Rechargeable:</strong> Up to 15 sessions per charge.</li>' +
        '</ul>';
    } else {
      body.innerHTML = '<h3 style="font-size: 20px; font-weight: 800; color: #1A202C; margin-top:0;">Zavelyn LED Red Light Face Mask</h3>' +
        '<p style="color: #64748B; font-size: 14px; line-height: 1.6;">Full-coverage facial LED mask utilizing optimal 630nm wavelength red diodes for daily at-home facial rejuvenation.</p>' +
        '<ul style="color: #334155; font-size: 14px; line-height: 1.8; padding-left: 20px;">' +
        '<li><strong>Full Face Coverage:</strong> Distributes red photon energy across forehead, cheeks, and jawline.</li>' +
        '<li><strong>Food-Grade Silicone:</strong> Conforms snugly to all facial contours.</li>' +
        '<li><strong>Zero UV Radiation:</strong> 100% safe, non-invasive photon cellular vitality.</li>' +
        '<li><strong>Handheld Remote:</strong> 1-touch operation with auto shut-off.</li>' +
        '</ul>';
    }
    modal.classList.add('active');
    document.body.style.overflow = 'hidden';
  };

  window.closeVfitModal = function() {
    const modal = document.getElementById('zvSelfCareModal');
    if (modal) {
      modal.classList.remove('active');
      document.body.style.overflow = '';
    }
  };

  recalculate();
})();
</script>

import { getAccessToken, SHOP, API_VERSION } from './batch1_config.mjs';
import fs from 'fs';

const DRAFT_THEME_ID = '187720335545';

async function uploadAsset(token, themeId, key, value) {
  const url = `https://${SHOP}/admin/api/${API_VERSION}/themes/${themeId}/assets.json`;
  const res = await fetch(url, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': token
    },
    body: JSON.stringify({
      asset: { key, value }
    })
  });
  const data = await res.json();
  if (data.errors) {
    throw new Error(`Upload error for ${key}: ${JSON.stringify(data.errors)}`);
  }
  console.log(`✓ Uploaded ${key} to Draft Theme ${themeId} (${value.length} chars)`);
}

async function renameTheme(token, themeId, newName) {
  const url = `https://${SHOP}/admin/api/${API_VERSION}/themes/${themeId}.json`;
  const res = await fetch(url, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': token
    },
    body: JSON.stringify({
      theme: { id: themeId, name: newName }
    })
  });
  const data = await res.json();
  console.log(`✓ Renamed Draft Theme ${themeId} to: "${data.theme?.name}"`);
}

async function main() {
  const token = await getAccessToken();

  // 1. Rename theme for clarity
  await renameTheme(token, DRAFT_THEME_ID, '[Draft Preview] Zavelyn - vFit Self-Care Upsell (Version A)');

  // 2. Upload snippets/vfit-selfcare-upsell.liquid
  const snippetContent = fs.readFileSync('snippets/vfit-selfcare-upsell.liquid', 'utf8');
  await uploadAsset(token, DRAFT_THEME_ID, 'snippets/vfit-selfcare-upsell.liquid', snippetContent);

  // 3. Update sections/zavelyn-pdp-main.liquid on Draft Theme
  const mainRes = await fetch(`https://${SHOP}/admin/api/${API_VERSION}/themes/${DRAFT_THEME_ID}/assets.json?asset[key]=sections/zavelyn-pdp-main.liquid`, {
    headers: { 'X-Shopify-Access-Token': token }
  });
  const mainData = await mainRes.json();
  let mainContent = mainData.asset.value;

  console.log(`Current zavelyn-pdp-main.liquid length: ${mainContent.length}`);

  // Find the end of .zv-pdp-layout inside .zv-pdp-section-wrap
  // Target pattern:
  //           </div><!-- end zv-pdp-layout -->
  //         </div><!-- end zv-pdp-container -->
  //       </div><!-- end zv-pdp-section-wrap -->

  // Let's locate where .zv-pdp-layout ends:
  // In zavelyn-pdp-main.liquid, after right column buy box closes:
  // </div> (for buybox)
  // </div> (for zv-pdp-layout)
  // </div> (for zv-pdp-container)
  // </div> (for zv-pdp-section-wrap)

  const layoutEndPattern = `      </div>\n    </div>\n  </div>\n</div>\n\n<style>`;
  const layoutEndAlt = `      </div>\n    </div>\n  </div>\n</div>`;

  const upsellInjection = `      </div>\n    </div>\n  </div>\n\n  {%- if product.handle == 'zavelyn-vfit-red-light-intimate-wellness-device' -%}\n    {%- render 'vfit-selfcare-upsell' -%}\n  {%- endif -%}\n</div>`;

  if (mainContent.includes(layoutEndPattern)) {
    mainContent = mainContent.replace(layoutEndPattern, upsellInjection + `\n\n<style>`);
    console.log('✓ Successfully injected vfit-selfcare-upsell right below zv-pdp-layout');
  } else if (mainContent.includes(layoutEndAlt)) {
    mainContent = mainContent.replace(layoutEndAlt, upsellInjection);
    console.log('✓ Successfully injected vfit-selfcare-upsell (alt match)');
  } else {
    // Search for end of info-col
    const infoColEnd = `      </div>\n    </div>\n  </div>`;
    console.log('Searching for alternative insertion point...');
    const searchIdx = mainContent.indexOf('<!-- RIGHT COLUMN: BUY BOX');
    if (searchIdx > -1) {
      const closingSlice = mainContent.substring(searchIdx, searchIdx + 40000);
      const lastLayoutDiv = closingSlice.indexOf('</div>\n    </div>\n  </div>\n</div>');
      if (lastLayoutDiv > -1) {
        const fullTarget = closingSlice.substring(lastLayoutDiv, lastLayoutDiv + 38);
        console.log('Found full target in buybox slice:', JSON.stringify(fullTarget));
      }
    }
  }

  // Upload updated sections/zavelyn-pdp-main.liquid to Draft Theme
  await uploadAsset(token, DRAFT_THEME_ID, 'sections/zavelyn-pdp-main.liquid', mainContent);

  console.log('\nSUCCESS: vFit Self-Care Upsell (Version A) deployed to DRAFT THEME (187720335545)');
}

main().catch(err => {
  console.error('Fatal during draft deployment:', err);
  process.exit(1);
});

