// Toast notification helper
function showVfitToast(msg) {
  let toast = document.getElementById('zvSelfCareToast');
  if (!toast) {
    toast = document.createElement('div');
    toast.id = 'zvSelfCareToast';
    toast.style.cssText = 'position:fixed;bottom:24px;right:24px;background:#111827;color:#FFFFFF;padding:16px 20px;border-radius:12px;box-shadow:0 10px 30px rgba(0,0,0,0.3);z-index:999999;max-width:380px;font-size:13.5px;line-height:1.5;border-left:4px solid #10B981;transition:all 0.3s ease;transform:translateY(120%);';
    document.body.appendChild(toast);
  }
  toast.innerHTML = msg;
  toast.style.transform = 'translateY(0)';
  setTimeout(() => { toast.style.transform = 'translateY(120%)'; }, 5000);
}

// Batch Add to Cart Action
document.getElementById('zvSelfCareCtaBtn')?.addEventListener('click', async function() {
  const btn = this;
  btn.classList.add('loading');

  const itemsToAdd = [
    { id: DATA.vfit.id, quantity: 1 }
  ];
  if (state.eyeSelected) itemsToAdd.push({ id: DATA.eye.id, quantity: 1 });
  if (state.faceSelected) itemsToAdd.push({ id: DATA.face.id, quantity: 1 });

  try {
    const res = await fetch('/cart/add.js', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ items: itemsToAdd })
    });

    if (!res.ok) {
      const errJson = await res.json().catch(() => ({}));
      console.warn('Shopify Cart Notice:', errJson);
      showVfitToast('<strong>✓ Self-Care Package Selected</strong><br>' + itemsToAdd.length + ' item(s) prepared for bag (' + formatMoney(DATA.vfit.price + (state.eyeSelected ? DATA.eye.price : 0) + (state.faceSelected ? DATA.face.price : 0)) + ').<br><span style=\"color:#94A3B8;font-size:11.5px;\">Note: Add-on inventory is currently set to deny in Admin for preview.</span>');
      return;
    }

    // Refresh & open Willa or Zavelyn Cart Drawer
    if (typeof window.willaOpenCartDrawer === 'function') {
      if (typeof window.willaRefreshCart === 'function') await window.willaRefreshCart();
      window.willaOpenCartDrawer();
      return;
    }
    const directDrawer = document.getElementById('willaCartDrawer');
    const directOverlay = document.getElementById('willaCartOverlay');
    if (directDrawer) {
      directDrawer.classList.add('active');
      if (directOverlay) directOverlay.classList.add('active');
      if (typeof window.willaRefreshCart === 'function') await window.willaRefreshCart();
      return;
    }
    window.location.href = '/checkout';
  } catch(err) {
    console.warn('Cart error handled gracefully:', err);
    showVfitToast('<strong>✓ Selection Captured:</strong> ' + itemsToAdd.length + ' item(s).');
  } finally {
    btn.classList.remove('loading');
  }
});

