  --zv-bg-card: #FFFFFF;
  --zv-bg-card-selected: #F3F8F5;
  --zv-bg-badge-rose: #FBF0ED;
  --zv-bg-badge-green: #EAF4EE;

  --zv-color-primary: #183324;      /* Deep Forest Green */
  --zv-color-accent: #234E3E;       /* Rich Botanical Green */
  --zv-color-rose: #C86D61;         /* Warm Rose Gold */
  --zv-color-rose-dark: #A4493D;
  --zv-color-text-main: #1D2939;    /* Dark Charcoal */
  --zv-color-text-muted: #667085;   /* Neutral Gray */
  --zv-color-text-light: #98A2B3;

  --zv-border-light: #EFE6E1;
  --zv-border-card: #EAE0DA;
  --zv-border-selected: #234E3E;

  --zv-shadow-card: 0 10px 30px rgba(24, 51, 36, 0.05);
