<script>
(function() {
  'use strict';

  const DATA = {
    vfit: {
      id: {{ vfit_var_id }},
      price: {{ vfit_price | divided_by: 100.0 }},
      comparePrice: {{ vfit_compare | divided_by: 100.0 }}
    },
    eye: {
      id: {{ eye_var_id }},
      price: {{ eye_price | divided_by: 100.0 }},
      comparePrice: {{ eye_compare | divided_by: 100.0 }}
    },
    face: {
      id: {{ face_var_id }},
      price: {{ face_price | divided_by: 100.0 }},
      comparePrice: {{ face_compare | divided_by: 100.0 }}
    }
  };

  const state = {
    vfitQuantity: 1,
    eyeSelected: false,
    faceSelected: false,
    galleries: {
      eyeMask: { activeIndex: 0 },
      faceMask: { activeIndex: 0 }
    }
  };

  function formatMoney(centsOrNum) {
    return '$' + Number(centsOrNum).toFixed(2);
  }

  function getActiveVfitQty() {
    const qtyDisplay = document.getElementById('vfitQtyDisplay');
    if (qtyDisplay) {
      const q = parseInt(qtyDisplay.textContent.trim(), 10);
      if (!isNaN(q) && q >= 1) return q;
    }
    const qtyInput = document.querySelector('input[name="quantity"]');
    if (qtyInput) {
      const q = parseInt(qtyInput.value, 10);
      if (!isNaN(q) && q >= 1) return q;
    }
    return state.vfitQuantity;
  }

  function recalculate() {
    state.vfitQuantity = getActiveVfitQty();
    const qty = state.vfitQuantity;
    const vfitTotal = DATA.vfit.price * qty;
    const vfitCompareTotal = DATA.vfit.comparePrice * qty;

    let total = vfitTotal;
    let compare = vfitCompareTotal;
    let addonsCount = 0;

    if (state.eyeSelected) {
      total += DATA.eye.price;
      compare += DATA.eye.comparePrice;
      addonsCount++;
    }
    if (state.faceSelected) {
      total += DATA.face.price;
      compare += DATA.face.comparePrice;
      addonsCount++;
    }

    const savings = compare - total;

    // Update Elements
    const nameEl = document.getElementById('zvSummaryVfitName');
    const priceEl = document.getElementById('zvSummaryVfitPrice');
    const eyeRow = document.getElementById('zvSummaryEye');
    const faceRow = document.getElementById('zvSummaryFace');
    const tierBadge = document.getElementById('zvSummaryTierBadge');
    const totalEl = document.getElementById('zvSummaryTotal');
    const compareEl = document.getElementById('zvSummaryCompare');
    const savingsEl = document.getElementById('zvSummarySavings');
    const ctaLabel = document.getElementById('zvSelfCareCtaLabel');

    if (nameEl) nameEl.textContent = 'Zavelyn vFit™ Red Light Device × ' + qty;
    if (priceEl) priceEl.textContent = formatMoney(vfitTotal);
    if (eyeRow) eyeRow.style.display = state.eyeSelected ? 'flex' : 'none';
    if (faceRow) faceRow.style.display = state.faceSelected ? 'flex' : 'none';

    if (tierBadge) {
      if (addonsCount === 0) tierBadge.textContent = qty > 1 ? 'CORE WELLNESS (' + qty + ' UNITS)' : 'CORE INTIMATE WELLNESS';
      else if (addonsCount === 1) tierBadge.textContent = state.eyeSelected ? 'DUO EYE & WELLNESS RITUAL' : 'DUO FACIAL & WELLNESS RITUAL';
      else tierBadge.textContent = 'COMPLETE 3-PIECE REJUVENATION SUITE';
    }

    if (totalEl) totalEl.textContent = formatMoney(total);
    if (compareEl) compareEl.textContent = formatMoney(compare);
    if (savingsEl) savingsEl.textContent = 'TOTAL SAVINGS VS. MSRP: ' + formatMoney(savings) + ' (BASED ON VERIFIED LIST PRICES)';

    if (ctaLabel) {
      ctaLabel.textContent = addonsCount === 0
        ? 'CLAIM vFIT WELLNESS DEVICE — ' + formatMoney(total)
        : 'CLAIM YOUR WELLNESS PACKAGE — ' + formatMoney(total);
    }

    // Toggle card selected classes
    const cardEye = document.getElementById('zvCardEye');
    const pillEye = document.getElementById('pillEye');
    if (cardEye) {
      cardEye.classList.toggle('selected', state.eyeSelected);
      if (pillEye) pillEye.textContent = state.eyeSelected ? '✓ ADDED' : '+ ADD TO ORDER';
