  document.getElementById('vfitQtyPlus')?.addEventListener('click', () => setTimeout(recalculate, 50));
  document.getElementById('vfitQtyMinus')?.addEventListener('click', () => setTimeout(recalculate, 50));

  // Multi-item add to cart
  document.getElementById('zvSelfCareCtaBtn')?.addEventListener('click', async function() {
    const btn = this;
    btn.style.opacity = '0.7';

    const qty = getActiveVfitQty();
