      { id: DATA.vfit.id, quantity: qty }
    ];
    if (state.eyeSelected) items.push({ id: DATA.eye.id, quantity: 1, properties: { '_addon_routine': 'vFit' } });
    if (state.faceSelected) items.push({ id: DATA.face.id, quantity: 1, properties: { '_addon_routine': 'vFit' } });

