import WebSocket from 'ws';
import { spawn } from 'child_process';
import fs from 'fs';
import dns from 'dns';
dns.setDefaultResultOrder('ipv4first');

async function main() {
  const chromePath = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
  const userDataDir = 'C:\\Users\\Admin\\AppData\\Local\\Temp\\chrome_vfit_shot_' + Date.now();
  const chrome = spawn(chromePath, [
    '--headless=new',
    '--remote-debugging-port=9223',
    '--user-data-dir=' + userDataDir,
    '--window-size=1440,1100'
  ]);
  await new Promise(r => setTimeout(r, 1500));
  const ver = await fetch('http://127.0.0.1:9223/json/version').then(r => r.json());
  const ws = new WebSocket(ver.webSocketDebuggerUrl);
  await new Promise(r => ws.on('open', r));

  let id = 1;
  const send = (method, params = {}) => new Promise((resolve) => {
    const cur = id++;
    const handler = (data) => {
      const msg = JSON.parse(data.toString());
      if (msg.id === cur) {
        ws.off('message', handler);
        resolve(msg);
      }
    };
    ws.on('message', handler);
    ws.send(JSON.stringify({ id: cur, method, params }));
  });

  await send('Page.enable');
  await send('Page.navigate', {
    url: 'https://dsdujr-vn.myshopify.com/products/zavelyn-vfit-red-light-intimate-wellness-device?preview_theme_id=187720335545'
  });
  await new Promise(r => setTimeout(r, 4500));

  // Dismiss cookie banner & setup multi-quantity: 2 vfit, 2 eye, 2 face
  await send('Runtime.evaluate', {
    expression: `(() => {
      const banner = document.querySelector('#shopify-pc__banner') || document.querySelector('[aria-label="Cookie consent"]');
      if (banner) banner.style.display = 'none';
      const cookieButtons = Array.from(document.querySelectorAll('button'));
      const acceptBtn = cookieButtons.find(b => b.textContent && b.textContent.includes('Accept'));
      if (acceptBtn) acceptBtn.click();

      // Set vFit = 2
      document.getElementById('vfitQtyPlus')?.click();

      // Select Eye & Face, set each to 2
      document.getElementById('zvCardEye')?.click();
      window.changeAddonQty('eyeMask', 1);

      document.getElementById('zvCardFace')?.click();
      window.changeAddonQty('faceMask', 1);

      // Scroll to summary card
      document.getElementById('zvOrderSummaryCard')?.scrollIntoView({ behavior: 'instant', block: 'center' });
    })()`
  });
  await new Promise(r => setTimeout(r, 800));

  const res = await send('Page.captureScreenshot', { format: 'png' });
  const outPath = 'C:\\Users\\Admin\\.gemini\\antigravity-ide\\brain\\d0f634e2-c9dd-4bad-bdb2-3c956abea303\\draft_theme_vfit_summary_detail.png';
  fs.writeFileSync(outPath, Buffer.from(res.result.data, 'base64'));
  console.log('Saved summary detail screenshot:', outPath);

  ws.close();
  chrome.kill();
  try { fs.rmSync(userDataDir, { recursive: true, force: true }); } catch (e) {}
}
main();

