import fs from 'fs';
import path from 'path';
import { getAccessToken, SHOP } from './batch1_config.mjs';
import dns from 'dns';
dns.setDefaultResultOrder('ipv4first');

const LIVE_THEME_ID = 187597717689; // Live Theme "Zavelyn 2.0"
const DRAFT_THEME_ID = 187720335545; // Source of truth tested Draft Theme

async function uploadAsset(token, key, value, isBinary = false) {
  const payload = { asset: { key } };
  if (isBinary) {
    payload.asset.attachment = value.toString('base64');
  } else {
    payload.asset.value = value;
  }

  const res = await fetch(`https://${SHOP}/admin/api/2024-01/themes/${LIVE_THEME_ID}/assets.json`, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': token
    },
    body: JSON.stringify(payload)
  });

  const data = await res.json();
  if (res.ok && data.asset) {
    console.log(`✓ Uploaded ${key} (${data.asset.size || value.length} bytes) to Live Theme`);
    return true;
  } else {
    console.error(`✗ Failed to upload ${key} to Live Theme:`, data);
    throw new Error(`Upload failed for ${key}: ` + JSON.stringify(data));
  }
}

async function getAsset(token, themeId, key) {
  const res = await fetch(`https://${SHOP}/admin/api/2024-01/themes/${themeId}/assets.json?asset[key]=${encodeURIComponent(key)}`, {
    headers: { 'X-Shopify-Access-Token': token }
  });
  if (!res.ok) return null;
  const data = await res.json();
  return data.asset;
}

async function main() {
  console.log(`=== EXECUTING SAFE DEPLOYMENT OF vFIT TO LIVE THEME (${LIVE_THEME_ID}) ===`);
  const token = await getAccessToken();

  // 0. Double-check Live Theme role
  const themesRes = await fetch(`https://${SHOP}/admin/api/2024-01/themes/${LIVE_THEME_ID}.json`, {
    headers: { 'X-Shopify-Access-Token': token }
  });
  const themeData = await themesRes.json();
  if (themeData.theme.role !== 'main') {
    throw new Error(`Target theme ${LIVE_THEME_ID} is not role main: ${themeData.theme.role}`);
  }
  console.log(`✓ Confirmed Live Theme: "${themeData.theme.name}" (ID: ${LIVE_THEME_ID}, role: main)`);

  // 1. Back up current Live Theme sections/zavelyn-pdp-main.liquid
  const backupDir = `backups/live_pre_deploy_vfit_${Date.now()}`;
  fs.mkdirSync(backupDir, { recursive: true });
  const livePdpMain = await getAsset(token, LIVE_THEME_ID, 'sections/zavelyn-pdp-main.liquid');
  fs.writeFileSync(`${backupDir}/sections__zavelyn-pdp-main.liquid`, livePdpMain.value);
  console.log(`✓ Safety backup created: ${backupDir}/sections__zavelyn-pdp-main.liquid`);

  // 2. Upload the 8 Gallery Images to Live Theme
  const mediaFiles = [
    'eyemask_source_hd.jpg',
    'eyemask_slide_2.jpg',
    'eyemask_slide_3.jpg',
    'eyemask_slide_4.jpg',
    'facemask_source_hd.jpg',
    'facemask_slide_2.jpg',
    'facemask_slide_3.jpg',
    'facemask_slide_4.jpg'
  ];

  console.log('\n--- 1. UPLOADING GALLERY IMAGES TO LIVE THEME ---');
  for (const filename of mediaFiles) {
    const filePath = path.resolve('prototypes/vfit-selfcare-upsell/media', filename);
    if (fs.existsSync(filePath)) {
      const buf = fs.readFileSync(filePath);
      await uploadAsset(token, `assets/${filename}`, buf, true);
    } else {
      throw new Error(`Required media asset missing: ${filePath}`);
    }
  }

  // 3. Upload snippets/vfit-selfcare-upsell.liquid to Live Theme
  console.log('\n--- 2. UPLOADING SNIPPET TO LIVE THEME ---');
  const snippetPath = path.resolve('snippets/vfit-selfcare-upsell.liquid');
  const snippetContent = fs.readFileSync(snippetPath, 'utf8');
  await uploadAsset(token, 'snippets/vfit-selfcare-upsell.liquid', snippetContent, false);

  // 4. Fetch the verified sections/zavelyn-pdp-main.liquid from Draft Theme and upload to Live Theme
  console.log('\n--- 3. SYNCING TESTED PDP SECTION TO LIVE THEME ---');
  const draftPdpAsset = await getAsset(token, DRAFT_THEME_ID, 'sections/zavelyn-pdp-main.liquid');
  if (!draftPdpAsset || !draftPdpAsset.value) {
    throw new Error('Could not fetch verified sections/zavelyn-pdp-main.liquid from Draft Theme');
  }

  // Extra safety sanity check on content
  if (!draftPdpAsset.value.includes("product.handle == 'zavelyn-botanaroots-organic-batana-hair-growth-oil'")) {
    throw new Error('SANITY CHECK FAILED: BotanaRoots isolation block missing from payload!');
  }
  if (!draftPdpAsset.value.includes("product.handle == 'zavelyn-vfit-red-light-intimate-wellness-device'")) {
    throw new Error('SANITY CHECK FAILED: vFit Buy Box block missing from payload!');
  }
  if (!draftPdpAsset.value.includes("zvClaimOfferBtn")) {
    throw new Error('SANITY CHECK FAILED: Claim offer button missing from payload!');
  }
  if (!draftPdpAsset.value.includes("vfit-selfcare-upsell")) {
    throw new Error('SANITY CHECK FAILED: vfit-selfcare-upsell render snippet missing from payload!');
  }

  await uploadAsset(token, 'sections/zavelyn-pdp-main.liquid', draftPdpAsset.value, false);

  console.log('\n✨ LIVE THEME DEPLOYMENT COMPLETED SUCCESSFULLY!');
}

main().catch(err => {
  console.error('Fatal in deploy_vfit_to_live_theme:', err);
  process.exit(1);
});

import { spawn } from 'child_process';
import fs from 'fs';
import dns from 'dns';
dns.setDefaultResultOrder('ipv4first');

const CDP_PORT = 9310;
const userDataDir = `${process.env.TEMP}\\chrome-live-vfit-${Date.now()}`;
const ARTIFACTS_DIR = 'C:\\Users\\Admin\\.gemini\\antigravity-ide\\brain\\d0f634e2-c9dd-4bad-bdb2-3c956abea303';

async function main() {
  const chromePath = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
  const chrome = spawn(chromePath, [
    '--headless=new',
    `--remote-debugging-port=${CDP_PORT}`,
    `--user-data-dir=${userDataDir}`,
    '--window-size=1440,1100'
  ]);
  await new Promise(r => setTimeout(r, 1500));

  const resTabs = await fetch(`http://127.0.0.1:${CDP_PORT}/json`);
  const tabs = await resTabs.json();
  const tab = tabs.find(t => t.type === 'page' && t.webSocketDebuggerUrl);

  const ws = new WebSocket(tab.webSocketDebuggerUrl);
  await new Promise(r => ws.addEventListener('open', r));

  let idCounter = 1;
  function send(method, params = {}) {
    return new Promise((resolve, reject) => {
      const id = idCounter++;
      const handler = evt => {
        const msg = JSON.parse(evt.data.toString());
        if (msg.id === id) {
          ws.removeEventListener('message', handler);
          if (msg.error) reject(msg.error);
          else resolve(msg.result);
        }
      };
      ws.addEventListener('message', handler);
      ws.send(JSON.stringify({ id, method, params }));
    });
  }

  await send('Page.enable');

  console.log('\n======================================================');
  console.log('1. VERIFYING vFIT ON OFFICIAL LIVE STOREFRONT (MAIN THEME)');
  console.log('======================================================');
  await send('Page.navigate', {
    url: 'https://dsdujr-vn.myshopify.com/products/zavelyn-vfit-red-light-intimate-wellness-device'
  });
  await new Promise(r => setTimeout(r, 5000));

  // Dismiss cookie banner
  await send('Runtime.evaluate', {
    expression: `(() => {
      document.querySelectorAll('#shopify-pc__banner, .shopify-policy-container, [aria-label*="cookie"], [class*="banner"]').forEach(el => el.remove());
    })()`
  });

  // Evaluate Buy Box Elements on Live Theme
  const buyBoxEval = await send('Runtime.evaluate', {
    returnByValue: true,
    expression: `(() => {
      const claimBtn = document.getElementById('zvClaimOfferBtn');
      const buyNowBtn = document.getElementById('zvBuyNowBtn');
      const urgencyBar = document.getElementById('zvUrgencyBar');
      const payIcons = document.querySelector('.zv-payment-icons-row');
      const starterCard = document.querySelector('.zv-buy1-container');
      const stepper = document.querySelector('.zv-qty-stepper');
      const qtyDisp = document.getElementById('vfitQtyDisplay');
      const priceCurrent = document.getElementById('zvPriceCurrent')?.innerText;
      const buy1Price = document.getElementById('zvBuy1Price')?.innerText;

      return {
        hasStarterCard: !!starterCard,
        hasStepper: !!stepper,
        qty: qtyDisp?.innerText,
        priceCurrent,
        buy1Price,
        hasUrgencyBar: !!urgencyBar,
        hasClaimBtn: !!claimBtn,
        claimBtnText: claimBtn?.innerText?.trim(),
        hasBuyNowBtn: !!buyNowBtn,
        hasPayIcons: !!payIcons
      };
    })()`
  });
  console.log('Live vFit Buy Box Status:');
  console.log(JSON.stringify(buyBoxEval.result.value, null, 2));

  // Capture Live Buy Box
  const shot1 = await send('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync(`${ARTIFACTS_DIR}\\live_vfit_buybox.png`, Buffer.from(shot1.data, 'base64'));
  console.log('✓ Captured live_vfit_buybox.png');

  // Test multi-quantity selection: 2 vFit, 2 Eye, 2 Face
  console.log('\nTesting multi-quantity (2 vFit + 2 Eye Mask + 2 Face Mask) on Live PDP...');
  const multiEval = await send('Runtime.evaluate', {
    returnByValue: true,
    expression: `(() => {
      // Increase vFit to 2
      document.getElementById('vfitQtyPlus')?.click();

      // Select Eye Mask and set qty to 2
      document.getElementById('zvCardEye')?.click();
      window.changeAddonQty('eyeMask', 1);

      // Select Face Mask and set qty to 2
      document.getElementById('zvCardFace')?.click();
      window.changeAddonQty('faceMask', 1);

      document.getElementById('zvOrderSummaryCard')?.scrollIntoView({ behavior: 'instant', block: 'center' });

      return {
        vfitSummary: document.getElementById('zvSummaryVfitName')?.innerText + ' (' + document.getElementById('zvSummaryVfitPrice')?.innerText + ')',
        eyeSummary: document.getElementById('zvSummaryEyeName')?.innerText + ' (' + document.getElementById('zvSummaryEyePrice')?.innerText + ')',
        faceSummary: document.getElementById('zvSummaryFaceName')?.innerText + ' (' + document.getElementById('zvSummaryFacePrice')?.innerText + ')',
        summaryTotal: document.getElementById('zvSummaryTotal')?.innerText,
        summarySavings: document.getElementById('zvSummarySavings')?.innerText,
        tierBadge: document.getElementById('zvSummaryTierBadge')?.innerText,
        ctaLabel: document.getElementById('zvSelfCareCtaLabel')?.innerText
      };
    })()`
  });
  console.log('Live Multi-Quantity Calculation Result:');
  console.log(JSON.stringify(multiEval.result.value, null, 2));

  await new Promise(r => setTimeout(r, 800));
  const shot2 = await send('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync(`${ARTIFACTS_DIR}\\live_vfit_multi_quantity_summary.png`, Buffer.from(shot2.data, 'base64'));
  console.log('✓ Captured live_vfit_multi_quantity_summary.png');

  // 2. Strict BotanaRoots Zero Bleed Verification on Live
  console.log('\n======================================================');
  console.log('2. VERIFYING BOTANAROOTS ON OFFICIAL LIVE STOREFRONT');
  console.log('======================================================');
  await send('Page.navigate', {
    url: 'https://dsdujr-vn.myshopify.com/products/zavelyn-botanaroots-organic-batana-hair-growth-oil'
  });
  await new Promise(r => setTimeout(r, 5000));

  const botanaEval = await send('Runtime.evaluate', {
    returnByValue: true,
    expression: `(() => {
      return {
        hasBotanaBundle: !!document.getElementById('zvBotanaBundleComponent'),
        hasBotanaCta: !!document.getElementById('zvBotanaCtaBtn'),
        botanaCtaText: document.getElementById('zvBotanaCtaBtn')?.innerText?.trim(),
        hasGenericClaimBtn: !!document.getElementById('zvClaimOfferBtn'),
        hasSelfCareSection: !!document.getElementById('zvSelfCareRoutine')
      };
    })()`
  });
  console.log('Live BotanaRoots Zero Bleed Status:');
  console.log(JSON.stringify(botanaEval.result.value, null, 2));

  const shot3 = await send('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync(`${ARTIFACTS_DIR}\\live_botanaroots_zero_bleed.png`, Buffer.from(shot3.data, 'base64'));
  console.log('✓ Captured live_botanaroots_zero_bleed.png');

  ws.close();
  chrome.kill();
  try { fs.rmSync(userDataDir, { recursive: true, force: true }); } catch (e) {}

  console.log('\n✨ ALL LIVE STOREFRONT POST-DEPLOYMENT CHECKS PASSED WITH 100% SUCCESS!');
}

main().catch(err => {
  console.error('Fatal in verify_live_storefront_vfit_post_deploy:', err);
  process.exit(1);
});

